        </Grid>
        <Border Background="#151E2B" BorderBrush="#334155" BorderThickness="1" CornerRadius="10" Padding="6">
         <ListView Name="DriverDeviceList" SelectionMode="Extended" Background="Transparent" Foreground="#E4E4E7" BorderThickness="0" MinHeight="260" MaxHeight="100000" ScrollViewer.HorizontalScrollBarVisibility="Auto" ScrollViewer.VerticalScrollBarVisibility="Auto" ScrollViewer.CanContentScroll="True" ScrollViewer.PanningMode="Both" VirtualizingPanel.IsVirtualizing="True" VirtualizingPanel.VirtualizationMode="Recycling">
          <ListView.Resources>
           <!-- Explicit dark row states prevent the default white hover/selection background from hiding text. -->
           <Style TargetType="ListViewItem">
            <Setter Property="Foreground" Value="#E4E4E7"/>
            <Setter Property="Background" Value="Transparent"/>
            <Setter Property="BorderThickness" Value="0"/>
            <Setter Property="Padding" Value="5,7"/>
            <Setter Property="HorizontalContentAlignment" Value="Stretch"/>
            <Setter Property="Template">
             <Setter.Value>
              <ControlTemplate TargetType="ListViewItem">
               <Border Name="DriverRowBorder" Background="{TemplateBinding Background}"
                       BorderBrush="#35506D" BorderThickness="0,0,0,1"
                       Padding="{TemplateBinding Padding}">
                <GridViewRowPresenter Content="{TemplateBinding Content}"
                 Columns="{Binding View.Columns, RelativeSource={RelativeSource AncestorType={x:Type ListView}}}"
                 VerticalAlignment="Center"/>
               </Border>
               <ControlTemplate.Triggers>
                <Trigger Property="IsMouseOver" Value="True">
                 <Setter TargetName="DriverRowBorder" Property="Background" Value="#263B52"/>
                 <Setter Property="Foreground" Value="#F1F5F9"/>
                </Trigger>
                <Trigger Property="IsSelected" Value="True">
                 <Setter TargetName="DriverRowBorder" Property="Background" Value="#1E4975"/>
                 <Setter TargetName="DriverRowBorder" Property="BorderBrush" Value="#4B83B8"/>
                 <Setter Property="Foreground" Value="#FFFFFF"/>
                </Trigger>
                <MultiTrigger>
                 <MultiTrigger.Conditions>
                  <Condition Property="IsSelected" Value="True"/>
                  <Condition Property="IsMouseOver" Value="True"/>
                 </MultiTrigger.Conditions>
                 <Setter TargetName="DriverRowBorder" Property="Background" Value="#285B8E"/>
                 <Setter Property="Foreground" Value="#FFFFFF"/>
                </MultiTrigger>
               </ControlTemplate.Triggers>
              </ControlTemplate>
             </Setter.Value>
            </Setter>
           </Style>
          </ListView.Resources>
          <ListView.View>
           <GridView>
            <GridViewColumn Header="Device" Width="245" DisplayMemberBinding="{Binding DeviceName}"/>
            <GridViewColumn Header="Class" Width="105" DisplayMemberBinding="{Binding DeviceClass}"/>
            <GridViewColumn Header="Manufacturer" Width="145" DisplayMemberBinding="{Binding Manufacturer}"/>
            <GridViewColumn Header="Status" Width="115" DisplayMemberBinding="{Binding StatusText}"/>
            <GridViewColumn Header="Driver Provider" Width="150" DisplayMemberBinding="{Binding DriverProvider}"/>
            <GridViewColumn Header="Installed Version" Width="135" DisplayMemberBinding="{Binding DriverVersion}"/>
            <GridViewColumn Header="Driver Date" Width="95" DisplayMemberBinding="{Binding DriverDate}"/>
            <GridViewColumn Header="Update Check" Width="190" DisplayMemberBinding="{Binding UpdateStatus}"/>
            <GridViewColumn Header="Match Confidence" Width="190" DisplayMemberBinding="{Binding MatchConfidence}"/>
            <GridViewColumn Header="Alternatives" Width="75" DisplayMemberBinding="{Binding MatchCandidateCount}"/>
            <GridViewColumn Header="Available Update" Width="250" DisplayMemberBinding="{Binding AvailableUpdate}"/>
            <GridViewColumn Header="Available Version" Width="130" DisplayMemberBinding="{Binding AvailableVersion}"/>
            <GridViewColumn Header="Code" Width="55" DisplayMemberBinding="{Binding ErrorCode}"/>
           </GridView>
          </ListView.View>
         </ListView>
        </Border>
        <TextBlock Text="Tip: select multiple device rows with Ctrl or Shift. Select All Ready marks every downloaded update; Install Selected Ready processes them one at a time after one confirmation. No automatic restart." Foreground="#8FB8E8" FontSize="10" TextWrapping="Wrap" Margin="4,8,4,0"/>
        <TextBlock Text="Driver updates are matched through Microsoft's Windows Update Agent. AMR compares all returned candidates: exact Hardware ID and more-specific IDs rank first, Compatible IDs rank lower, then model/manufacturer hints, driver version and date break ties. The best candidate is selected automatically and its confidence/alternative count are shown. Windows Update remains the authority on applicability. Check Driver Rollback reports matching Driver Store packages only; Device Manager's Roll Back Driver control is the authority for actual rollback availability. Review results before downloading or installing." Foreground="#94A3B8" FontSize="10" TextWrapping="Wrap" Margin="4,6,4,0"/>
       </StackPanel>
      </ScrollViewer>
     </TabItem>
     <TabItem Header="Update">
      <Grid Background="#18181B" Margin="10">
       <StackPanel VerticalAlignment="Top" Margin="12">
        <TextBlock Text="UPDATE CENTER" FontSize="24" FontWeight="Bold" Foreground="#F8FAFC"/>
        <TextBlock Text="Windows and driver update management will be added here." Foreground="#94A3B8" FontSize="12" TextWrapping="Wrap" Margin="0,6,0,0"/>
        <Border Background="#1B2432" BorderBrush="#334155" BorderThickness="1" CornerRadius="10" Padding="14" Margin="0,18,0,0" MaxWidth="620" HorizontalAlignment="Left">
         <TextBlock Text="Update Center is reserved for the upcoming update features." Foreground="#CBD5E1" FontSize="12" TextWrapping="Wrap"/>
        </Border>
       </StackPanel>
      </Grid>
     </TabItem>
    </TabControl>
   </TabItem>

   <!-- 2. SOFTWARE WITH INTEGRATED PROGRESS BAR -->
   <TabItem Header="Software" IsSelected="True">
    <Border Padding="10,0,10,20">
     <Grid>
      <Grid.RowDefinitions>
       <RowDefinition Height="Auto"/>
       <RowDefinition Height="*"/>
       <RowDefinition Height="Auto"/>
      </Grid.RowDefinitions>
      
      <Grid Grid.Row="0" Margin="0,10,0,20">
       <Grid.ColumnDefinitions>
        <ColumnDefinition Width="*"/>
        <ColumnDefinition Width="470"/>
       </Grid.ColumnDefinitions>
       <StackPanel Grid.Column="0" VerticalAlignment="Center">
        <TextBlock Text="Software Catalog" FontSize="22" FontWeight="Bold" Foreground="#FFFFFF"/>
        <TextBlock Text="Smart Multi-Tier Engine (Winget ➔ Chocolatey ➔ Strict Verified Direct Download)." Foreground="#A1A1AA" FontSize="11" TextWrapping="Wrap" Margin="0,3,0,0"/>
       </StackPanel>

       <Grid Grid.Column="1" VerticalAlignment="Center">
        <Grid.ColumnDefinitions>
         <ColumnDefinition Width="*"/>
         <ColumnDefinition Width="145"/>
        </Grid.ColumnDefinitions>
        <TextBox Name="SearchBox" Grid.Column="0" Height="42" Margin="0,0,8,0" VerticalAlignment="Center" FontSize="15" ToolTip="Search by name or ID..."/>
        <TextBlock Grid.Column="0" Text="🔍 Search name or ID..." IsHitTestVisible="False" VerticalAlignment="Center" Margin="15,0,0,0" Foreground="#71717A" FontSize="14">
         <TextBlock.Style>
          <Style TargetType="TextBlock">
           <Setter Property="Visibility" Value="Hidden"/>
           <Style.Triggers>
            <DataTrigger Binding="{Binding Text.Length, ElementName=SearchBox}" Value="0">
             <Setter Property="Visibility" Value="Visible"/>
            </DataTrigger>
           </Style.Triggers>
          </Style>
         </TextBlock.Style>
        </TextBlock>
        <Button Name="ShowInstalledBtn" Grid.Column="1" Height="38" VerticalAlignment="Center" Padding="9,0" FontSize="12" FontWeight="SemiBold" Cursor="Hand" Content="Show Installed" ToolTip="Show only applications detected as installed on this PC." Background="#263B3A" Foreground="#A7D8CE" BorderBrush="#456B65" BorderThickness="1"/>
       </Grid>
      </Grid>
      
      <Grid Grid.Row="1" Margin="0,0,0,4">
       <Grid.ColumnDefinitions>
        <ColumnDefinition Width="*"/>
        <ColumnDefinition Width="205"/>
       </Grid.ColumnDefinitions>

       <Border Grid.Column="1" Margin="12,5,0,5" Background="#202B3B"
               BorderBrush="#30445F" BorderThickness="1" CornerRadius="10" Padding="10">
        <DockPanel LastChildFill="True">
         <TextBlock DockPanel.Dock="Top" Text="CATEGORIES" FontSize="11"
                    FontWeight="Bold" Foreground="#8FB8E8" Margin="5,3,5,10"/>
         <ListBox Name="SoftwareCategoryList"
                  Background="Transparent" BorderThickness="0" Foreground="#DCE8F7"
                  ScrollViewer.HorizontalScrollBarVisibility="Disabled"
                  ScrollViewer.VerticalScrollBarVisibility="Hidden"
                  SelectionMode="Single">
          <ListBox.ItemsPanel>
           <ItemsPanelTemplate><StackPanel Orientation="Vertical"/></ItemsPanelTemplate>
          </ListBox.ItemsPanel>
          <ListBox.Resources>
           <Style TargetType="ListBoxItem">
            <Setter Property="Foreground" Value="#C9D8EA"/>
            <Setter Property="Background" Value="#26364B"/>
            <Setter Property="Padding" Value="8,7"/>
            <Setter Property="Margin" Value="0,0,0,7"/>
            <Setter Property="HorizontalContentAlignment" Value="Stretch"/>
            <Setter Property="FontSize" Value="12"/>
            <Setter Property="Template">
             <Setter.Value>
              <ControlTemplate TargetType="ListBoxItem">
               <Border Name="CategoryTileBorder" Background="{TemplateBinding Background}"
                       BorderBrush="#344B68" BorderThickness="1" CornerRadius="7"
                       Padding="{TemplateBinding Padding}">
                <ContentPresenter HorizontalAlignment="Stretch" VerticalAlignment="Center"/>
               </Border>
               <ControlTemplate.Triggers>
                <Trigger Property="IsMouseOver" Value="True">
                 <Setter TargetName="CategoryTileBorder" Property="Background" Value="#304A6B"/>
                 <Setter TargetName="CategoryTileBorder" Property="BorderBrush" Value="#527AA8"/>
                </Trigger>
                <Trigger Property="IsSelected" Value="True">
                 <Setter TargetName="CategoryTileBorder" Property="Background" Value="#24558A"/>
                 <Setter TargetName="CategoryTileBorder" Property="BorderBrush" Value="#5B9BE0"/>
                 <Setter Property="Foreground" Value="#FFFFFF"/>
                 <Setter Property="FontWeight" Value="SemiBold"/>
                </Trigger>
               </ControlTemplate.Triggers>
              </ControlTemplate>
             </Setter.Value>
            </Setter>
           </Style>
          </ListBox.Resources>
         </ListBox>
        </DockPanel>
       </Border>

       <ScrollViewer Grid.Column="0" FlowDirection="RightToLeft" VerticalScrollBarVisibility="Auto" HorizontalScrollBarVisibility="Disabled">
        
       <ItemsControl Name="SoftwareGrid" FlowDirection="LeftToRight" Margin="0,5,0,0">
        <ItemsControl.ItemsPanel>
         <ItemsPanelTemplate><UniformGrid Columns="3"/></ItemsPanelTemplate>
        </ItemsControl.ItemsPanel>
        
        <ItemsControl.ItemTemplate>
         <DataTemplate>
          <Border Background="#27272A" BorderBrush="#3F3F46" BorderThickness="1" CornerRadius="9" Padding="10" Margin="6" MaxWidth="260" HorizontalAlignment="Stretch" VerticalAlignment="Center">
           <Grid>
            <Grid.ColumnDefinitions>
             <ColumnDefinition Width="Auto"/>
             <ColumnDefinition Width="Auto"/>
             <ColumnDefinition Width="*"/>
            </Grid.ColumnDefinitions>
            <CheckBox IsChecked="{Binding IsSelected, UpdateSourceTrigger=PropertyChanged}" VerticalAlignment="Center" Margin="0,0,15,0">
             <CheckBox.LayoutTransform><ScaleTransform ScaleX="1.2" ScaleY="1.2"/></CheckBox.LayoutTransform>
            </CheckBox>
            <Grid Grid.Column="1" Width="40" Height="40" Margin="0,0,10,0">
             <Border Background="#3F3F46" CornerRadius="10"/>
             <TextBlock Text="{Binding Initials}" Foreground="#A1A1AA" FontSize="17" FontWeight="Bold" HorizontalAlignment="Center" VerticalAlignment="Center">
              <TextBlock.Style>
               <Style TargetType="TextBlock">
                <Setter Property="Visibility" Value="Collapsed"/>
                <Style.Triggers>
                 <DataTrigger Binding="{Binding Icon}" Value="{x:Null}">
                  <Setter Property="Visibility" Value="Visible"/>
                 </DataTrigger>
                </Style.Triggers>
               </Style>
              </TextBlock.Style>
             </TextBlock>
             <Image Source="{Binding Icon, Mode=OneWay, TargetNullValue={x:Null}, FallbackValue={x:Null}}" Width="32" Height="32" Stretch="Uniform" HorizontalAlignment="Center" VerticalAlignment="Center" SnapsToDevicePixels="True" RenderOptions.BitmapScalingMode="HighQuality"/>
            </Grid>
            <StackPanel Grid.Column="2" VerticalAlignment="Center">
             <TextBlock Text="{Binding Name}" FontSize="14" FontWeight="SemiBold" Foreground="#FFFFFF" TextWrapping="Wrap"/>
             <TextBlock Text="{Binding Id}" FontSize="10" Foreground="#71717A" TextWrapping="Wrap" Margin="0,3,0,0"/>
            </StackPanel>
           </Grid>
          </Border>
         </DataTemplate>
        </ItemsControl.ItemTemplate>
       </ItemsControl>
       </ScrollViewer>
      </Grid>      
      <!-- App Console Bottom Bar & Progress Bar -->
      <Border Grid.Row="2" Background="#27272A" BorderBrush="#3F3F46" BorderThickness="1" CornerRadius="12" Padding="20" Margin="0,20,0,0">
       <Grid>
        <Grid.RowDefinitions>
         <RowDefinition Height="Auto"/>
         <RowDefinition Height="Auto"/>
        </Grid.RowDefinitions>
        
        <Grid Grid.Row="0">
         <Grid.ColumnDefinitions>
          <ColumnDefinition Width="*"/>
          <ColumnDefinition Width="Auto"/>
         </Grid.ColumnDefinitions>
         <StackPanel Grid.Column="0" VerticalAlignment="Center">
          <TextBlock Text="App Management Console" Foreground="#FFFFFF" FontSize="16" FontWeight="Bold"/>
          <TextBlock Name="ProgressText" Text="Ready to process selected apps." Foreground="#10B981" FontSize="13" Margin="0,4,0,0" FontWeight="SemiBold"/>
         </StackPanel>
         <StackPanel Grid.Column="1" Orientation="Horizontal" HorizontalAlignment="Right">
          <Button Name="DeselectAllBtn" Content="Clear Selection" Background="Transparent" Foreground="#A1A1AA" FontSize="14" Margin="0,0,15,0"/>
          <Button Name="RepairSelectedBtn" Content="🔧 Repair" Background="#EAB308" Foreground="#18181B" BorderThickness="0" FontSize="14" FontWeight="Bold" Margin="0,0,10,0"/>
          <Button Name="UninstallSelectedBtn" Content="🗑 Uninstall" Visibility="Collapsed" Background="#DC2626" Foreground="#FFFFFF" BorderBrush="#F87171" BorderThickness="1" Padding="14,10" FontSize="14" FontWeight="Bold" Margin="0,0,15,0" ToolTip="Safely uninstall selected installed applications."/>
          <Button Name="UpdateSelectedBtn" Content="⬆ Update" Background="#3B82F6" Foreground="#FFFFFF" BorderThickness="0" FontSize="14" FontWeight="Bold" Margin="0,0,15,0"/>
          <Button Name="InstallInteractiveBtn" Content="🖥 Interactive Install" Background="#8B5CF6" Foreground="#FFFFFF" BorderThickness="0" Padding="15,12" FontSize="14" FontWeight="Bold" Margin="0,0,10,0"/>
          <Button Name="InstallSelectedBtn" Content="⬇ Smart Install" Background="#10B981" Foreground="#FFFFFF" BorderThickness="0" Padding="20,12" FontSize="14" FontWeight="Bold"/>
         </StackPanel>
        </Grid>
        
        <!-- Live Progress Bar -->
        <ProgressBar Name="InstallProgressBar" Grid.Row="1" Height="8" Minimum="0" Maximum="100" Value="0" Background="#18181B" Foreground="#10B981" Margin="0,15,0,0" BorderThickness="0"/>
       </Grid>
      </Border>
     </Grid>
    </Border>
   </TabItem>

   <!-- 3. MEGA CUSTOMIZE SUITE (27 TOOLS & TWEAKS) -->
   <TabItem Header="Customize">
    <TabControl Name="CustomizeSubTabs" SelectedIndex="0" Style="{StaticResource OverviewSubTabControlStyle}" TabStripPlacement="Right" ItemContainerStyle="{StaticResource OverviewSubTabItemStyle}" Background="#18181B" BorderThickness="0" Margin="0,0,0,0">
     <TabItem Header="Tweaks" IsSelected="True">
<ScrollViewer VerticalScrollBarVisibility="Auto" HorizontalScrollBarVisibility="Disabled" Padding="8,0,4,8">
