$script:AppsView = [System.Windows.Data.CollectionViewSource]::GetDefaultView($script:SoftwareCatalog)

# Build category navigation entries with live catalog counts.
# Counts switch to installed-only totals whenever Show Installed is active.
$script:SelectedSoftwareCategory = 'All Applications'
$script:ShowInstalledOnly = $false
$script:SoftwareCategoryNames = @(
    $script:SoftwareCatalog |
        ForEach-Object { [string]$_.Category } |
        Where-Object { -not [string]::IsNullOrWhiteSpace($_) } |
        Sort-Object -Unique
)
$script:SoftwareCategories = @(
    [pscustomobject]@{ Name = 'All Applications'; DisplayText = 'All Applications (0)' }
) + @(
    foreach ($categoryName in $script:SoftwareCategoryNames) {
        [pscustomobject]@{ Name = [string]$categoryName; DisplayText = [string]$categoryName }
    }
)
$categoryTextFactory = New-Object System.Windows.FrameworkElementFactory([System.Windows.Controls.TextBlock])
$categoryTextFactory.SetBinding([System.Windows.Controls.TextBlock]::TextProperty, [System.Windows.Data.Binding]::new('DisplayText'))
$categoryTextFactory.SetValue([System.Windows.Controls.TextBlock]::TextWrappingProperty, [System.Windows.TextWrapping]::Wrap)
$categoryTextFactory.SetValue([System.Windows.Controls.TextBlock]::TextTrimmingProperty, [System.Windows.TextTrimming]::None)
$categoryTextFactory.SetValue([System.Windows.Controls.TextBlock]::FontSizeProperty, 11.5)
$categoryTextFactory.SetValue([System.Windows.Controls.TextBlock]::MaxWidthProperty, 175.0)
$categoryTemplate = [System.Windows.DataTemplate]::new()
$categoryTemplate.VisualTree = $categoryTextFactory
(C 'SoftwareCategoryList').ItemTemplate = $categoryTemplate
(C 'SoftwareCategoryList').ItemsSource = $script:SoftwareCategories
(C 'SoftwareCategoryList').SelectedIndex = 0

function Update-AMRSoftwareCategoryCounts {
    $catalogItems = @($script:SoftwareCatalog)
    $visibleItems = if ($script:ShowInstalledOnly) {
        @($catalogItems | Where-Object { $_.IsInstalled -eq $true })
    } else {
        $catalogItems
    }

    foreach ($categoryEntry in $script:SoftwareCategories) {
        if ($categoryEntry.Name -eq 'All Applications') {
            $count = $visibleItems.Count
        } else {
            $count = @($visibleItems | Where-Object { [string]$_.Category -eq [string]$categoryEntry.Name }).Count
        }
        $categoryEntry.DisplayText = '{0} ({1})' -f $categoryEntry.Name, $count
    }

    # Refresh the ListBox display without changing the selected category.
    $list = C 'SoftwareCategoryList'
    $selectedName = $script:SelectedSoftwareCategory
    $list.Items.Refresh()
    for ($i = 0; $i -lt $script:SoftwareCategories.Count; $i++) {
        if ($script:SoftwareCategories[$i].Name -eq $selectedName) {
            $list.SelectedIndex = $i
            break
        }
    }
}

Update-AMRSoftwareCategoryCounts
try { (C 'UninstallSelectedBtn').Visibility = 'Collapsed' } catch {}

function Update-AMRInstalledCatalogState {
    # Build a multi-source local inventory once, then match it against the catalog.
    # Evidence sources: Windows uninstall registry, AppX/MSIX, WinGet, Chocolatey and Scoop.
    # Provisioned AppX packages are intentionally excluded: provisioned does not mean installed.
    $installedIdentities = New-Object 'System.Collections.Generic.HashSet[string]' ([System.StringComparer]::OrdinalIgnoreCase)
    $wingetIdentities = New-Object 'System.Collections.Generic.HashSet[string]' ([System.StringComparer]::OrdinalIgnoreCase)
    $chocoIdentities = New-Object 'System.Collections.Generic.HashSet[string]' ([System.StringComparer]::OrdinalIgnoreCase)
    $scoopIdentities = New-Object 'System.Collections.Generic.HashSet[string]' ([System.StringComparer]::OrdinalIgnoreCase)

    # 1. Windows uninstall inventory: machine/user and 64-bit/32-bit registry locations.
    $registryEntryCount = 0
    $uninstallPaths = @(
        'HKLM:\Software\Microsoft\Windows\CurrentVersion\Uninstall\*',
        'HKLM:\Software\Wow6432Node\Microsoft\Windows\CurrentVersion\Uninstall\*',
        'HKCU:\Software\Microsoft\Windows\CurrentVersion\Uninstall\*',
        'HKCU:\Software\Wow6432Node\Microsoft\Windows\CurrentVersion\Uninstall\*'
    )
    foreach ($registryPath in $uninstallPaths) {
        try {
            foreach ($entry in @(Get-ItemProperty -Path $registryPath -ErrorAction SilentlyContinue)) {
                $displayNameProperty = $entry.PSObject.Properties['DisplayName']
                $childNameProperty = $entry.PSObject.Properties['PSChildName']
                $displayNameValue = if ($displayNameProperty -and $null -ne $displayNameProperty.Value) { [string]$displayNameProperty.Value } else { '' }
                $childNameValue = if ($childNameProperty -and $null -ne $childNameProperty.Value) { [string]$childNameProperty.Value } else { '' }
                if (-not [string]::IsNullOrWhiteSpace($displayNameValue)) { $registryEntryCount++ }
                foreach ($identity in @($displayNameValue, $childNameValue)) {
                    if (-not [string]::IsNullOrWhiteSpace($identity)) {
                        $normalized = ($identity -replace '[^a-zA-Z0-9]', '').ToLowerInvariant()
                        if ($normalized.Length -ge 3) { [void]$installedIdentities.Add($normalized) }
                    }
                }
            }
        } catch {
            Write-AMRLog "Could not read installed software inventory from '$registryPath': $($_.Exception.Message)" WARNING Software
        }
    }

    # 2. AppX/MSIX packages installed for the current user or any user on this PC.
    $appxPackageCount = 0
    try {
        $appxPackages = @(Get-AppxPackage -AllUsers -ErrorAction Stop)
    } catch {
        Write-AMRLog "All-user AppX inventory was unavailable; falling back to the current user: $($_.Exception.Message)" WARNING Software
        try { $appxPackages = @(Get-AppxPackage -ErrorAction SilentlyContinue) } catch { $appxPackages = @() }
    }
    foreach ($package in $appxPackages) {
        # When Windows exposes per-user package states, count only packages registered
        # as Installed for at least one user; do not count packages merely Staged.
        $userInfoProperty = $package.PSObject.Properties['PackageUserInformation']
        if ($userInfoProperty -and $null -ne $userInfoProperty.Value) {
            $hasInstalledUser = $false
            foreach ($userInfo in @($userInfoProperty.Value)) {
                if ([string]$userInfo.InstallState -eq 'Installed') { $hasInstalledUser = $true; break }
            }
            if (-not $hasInstalledUser) { continue }
        }
        $appxPackageCount++
        foreach ($identity in @([string]$package.Name, [string]$package.PackageFamilyName, [string]$package.PackageFullName)) {
            if (-not [string]::IsNullOrWhiteSpace($identity)) {
                $normalized = ($identity -replace '[^a-zA-Z0-9]', '').ToLowerInvariant()
                if ($normalized.Length -ge 3) { [void]$installedIdentities.Add($normalized) }
            }
        }
    }

    # 3. WinGet's own installed-package inventory. Parse only the ID column when possible;
    # the exact-ID fallback handles CLI table-layout differences without loose name matching.
    $wingetRawOutput = ''
    $wingetAvailable = $false
    try {
        $winget = Get-Command winget.exe -ErrorAction SilentlyContinue
        if ($winget) {
            $wingetAvailable = $true
            $wingetToken = [guid]::NewGuid().ToString('N')
            $wingetStdoutPath = Join-Path $env:TEMP ("AMR_ShowInstalled_{0}.out" -f $wingetToken)
            $wingetStderrPath = Join-Path $env:TEMP ("AMR_ShowInstalled_{0}.err" -f $wingetToken)
            $wingetProcess = $null
            $wingetExitCode = -1
            try {
                $wingetProcess = Start-Process -FilePath $winget.Source -ArgumentList 'list --disable-interactivity --accept-source-agreements' -PassThru -WindowStyle Hidden -RedirectStandardOutput $wingetStdoutPath -RedirectStandardError $wingetStderrPath -ErrorAction Stop
                if (-not $wingetProcess.WaitForExit(20000)) {
                    try { Stop-Process -Id $wingetProcess.Id -Force -ErrorAction SilentlyContinue } catch {}
                    throw 'WinGet installed-package inventory timed out after 20 seconds.'
                }
                $wingetProcess.WaitForExit()
                $wingetExitCode = [int]$wingetProcess.ExitCode
                $wingetStdout = if (Test-Path -LiteralPath $wingetStdoutPath) { [string](Get-Content -LiteralPath $wingetStdoutPath -Raw -ErrorAction SilentlyContinue) } else { '' }
                $wingetStderr = if (Test-Path -LiteralPath $wingetStderrPath) { [string](Get-Content -LiteralPath $wingetStderrPath -Raw -ErrorAction SilentlyContinue) } else { '' }
                $wingetRawOutput = $wingetStdout
                $wingetOutput = @($wingetStdout -split "`r?`n")
            } finally {
                if ($wingetProcess) { try { $wingetProcess.Dispose() } catch {} }
                foreach ($tempOutput in @($wingetStdoutPath,$wingetStderrPath)) {
                    if (Test-Path -LiteralPath $tempOutput) { Remove-Item -LiteralPath $tempOutput -Force -ErrorAction SilentlyContinue }
                }
            }
            if ($wingetExitCode -eq 0) {
                $headerIndex = -1
                $idColumnStart = -1
                $versionColumnStart = -1
                for ($lineIndex = 0; $lineIndex -lt $wingetOutput.Count; $lineIndex++) {
                    $lineText = [string]$wingetOutput[$lineIndex]
                    $idHeader = [regex]::Match($lineText, '(?i)\bId\b')
                    $versionHeader = [regex]::Match($lineText, '(?i)\bVersion\b')
                    if ($idHeader.Success -and $versionHeader.Success -and $versionHeader.Index -gt $idHeader.Index) {
                        $headerIndex = $lineIndex
                        $idColumnStart = $idHeader.Index
                        $versionColumnStart = $versionHeader.Index
                        break
                    }
                }
                if ($headerIndex -ge 0) {
                    for ($lineIndex = ($headerIndex + 1); $lineIndex -lt $wingetOutput.Count; $lineIndex++) {
                        $lineText = [string]$wingetOutput[$lineIndex]
                        if ($lineText.Length -le $idColumnStart) { continue }
                        $fieldLength = [Math]::Min(($versionColumnStart - $idColumnStart), ($lineText.Length - $idColumnStart))
                        if ($fieldLength -le 0) { continue }
                        $packageId = $lineText.Substring($idColumnStart, $fieldLength).Trim()
                        if ($packageId -match '^[A-Za-z0-9][A-Za-z0-9._-]*$') {
                            $normalizedId = ($packageId -replace '[^a-zA-Z0-9]', '').ToLowerInvariant()
                            if ($normalizedId.Length -ge 3) { [void]$wingetIdentities.Add($normalizedId) }
                        }
                    }
                }
            } else {
                Write-AMRLog ("WinGet installed-package inventory returned exit code {0}; registry/AppX detection will still be used. {1}" -f $wingetExitCode,$wingetStderr) WARNING Software
            }
        }
    } catch {
        Write-AMRLog "Could not read WinGet installed-package inventory: $($_.Exception.Message)" WARNING Software
    }

    # 4. Chocolatey local package folders are authoritative for Chocolatey-managed installs.
    $chocoRoots = @()
    if (-not [string]::IsNullOrWhiteSpace($env:ChocolateyInstall)) { $chocoRoots += $env:ChocolateyInstall }
    $chocoRoots += (Join-Path $env:ProgramData 'chocolatey')
    foreach ($chocoRoot in @($chocoRoots | Select-Object -Unique)) {
        $chocoLib = Join-Path $chocoRoot 'lib'
        if (-not (Test-Path -LiteralPath $chocoLib -PathType Container)) { continue }
        try {
            foreach ($packageFolder in @(Get-ChildItem -LiteralPath $chocoLib -Directory -ErrorAction SilentlyContinue)) {
                $nuspecFiles = @(Get-ChildItem -LiteralPath $packageFolder.FullName -Filter '*.nuspec' -File -ErrorAction SilentlyContinue)
                if ($nuspecFiles.Count -gt 0) {
                    $normalizedFolder = ($packageFolder.Name -replace '[^a-zA-Z0-9]', '').ToLowerInvariant()
                    if ($normalizedFolder.Length -ge 3) { [void]$chocoIdentities.Add($normalizedFolder) }
                }
            }
        } catch {
            Write-AMRLog "Could not read Chocolatey package inventory at '$chocoLib': $($_.Exception.Message)" WARNING Software
        }
    }

    # 5. Scoop app folders (user and global installations).
    $scoopRoots = @()
    if (-not [string]::IsNullOrWhiteSpace($env:SCOOP)) { $scoopRoots += $env:SCOOP }
    if (-not [string]::IsNullOrWhiteSpace($env:SCOOP_GLOBAL)) { $scoopRoots += $env:SCOOP_GLOBAL }
    if (-not [string]::IsNullOrWhiteSpace($env:USERPROFILE)) { $scoopRoots += (Join-Path $env:USERPROFILE 'scoop') }
    if (-not [string]::IsNullOrWhiteSpace($env:ProgramData)) { $scoopRoots += (Join-Path $env:ProgramData 'scoop') }
    foreach ($scoopRoot in @($scoopRoots | Select-Object -Unique)) {
        $appsPath = Join-Path $scoopRoot 'apps'
        if (-not (Test-Path -LiteralPath $appsPath -PathType Container)) { continue }
        try {
            foreach ($appFolder in @(Get-ChildItem -LiteralPath $appsPath -Directory -ErrorAction SilentlyContinue)) {
                $normalizedFolder = ($appFolder.Name -replace '[^a-zA-Z0-9]', '').ToLowerInvariant()
                if ($normalizedFolder.Length -ge 3) { [void]$scoopIdentities.Add($normalizedFolder) }
            }
        } catch {
            Write-AMRLog "Could not read Scoop package inventory at '$appsPath': $($_.Exception.Message)" WARNING Software
        }
    }

    # Canonical aliases for known catalog/installer naming differences.
    $identityAliases = @{
        'everythingsearch' = @('everything')
        'visualstudiocode' = @('vscode','microsoftvisualstudiocode')
        'microsoftedgewebview2runtime' = @('webview2runtime','microsoftedgewebview2')
        'googlechrome' = @('chrome')
        'microsoftedge' = @('edge')
        'discord' = @('discord')
        '7zip' = @('7zip')
        'vlcmediaplayer' = @('vlc')
        'sumatrapdf' = @('sumatrapdf')
        'sharex' = @('sharex')
    }

    $installedCount = 0
    foreach ($app in $script:SoftwareCatalog) {
        $isInstalled = $false
        $candidateIdentities = New-Object 'System.Collections.Generic.List[string]'
        foreach ($identity in @([string]$app.Name, [string]$app.Id, [string]$app.ChocoId)) {
            if ([string]::IsNullOrWhiteSpace($identity)) { continue }
            $normalized = ($identity -replace '[^a-zA-Z0-9]', '').ToLowerInvariant()
            if ($normalized.Length -ge 3 -and -not $candidateIdentities.Contains($normalized)) { $candidateIdentities.Add($normalized) }
        }

        # The final segment of a package ID often matches its Windows display name
        # (for example, Vendor.ProductName vs. Product Name).
        if (-not [string]::IsNullOrWhiteSpace([string]$app.Id) -and [string]$app.Id -match '\.') {
            $idSuffix = ([string]$app.Id -split '\.')[-1]
            $normalizedSuffix = ($idSuffix -replace '[^a-zA-Z0-9]', '').ToLowerInvariant()
            if ($normalizedSuffix.Length -ge 3 -and -not $candidateIdentities.Contains($normalizedSuffix)) { $candidateIdentities.Add($normalizedSuffix) }
        }

        foreach ($baseIdentity in @($candidateIdentities.ToArray())) {
            if ($identityAliases.ContainsKey($baseIdentity)) {
                foreach ($alias in $identityAliases[$baseIdentity]) {
                    $normalizedAlias = ($alias -replace '[^a-zA-Z0-9]', '').ToLowerInvariant()
                    if ($normalizedAlias.Length -ge 3 -and -not $candidateIdentities.Contains($normalizedAlias)) { $candidateIdentities.Add($normalizedAlias) }
                }
            }
        }

        # Strong package-manager evidence: exact WinGet package ID, Chocolatey ID,
        # or Scoop app-folder identity.
        $normalizedCatalogId = ([string]$app.Id -replace '[^a-zA-Z0-9]', '').ToLowerInvariant()
        $normalizedChocoId = ([string]$app.ChocoId -replace '[^a-zA-Z0-9]', '').ToLowerInvariant()
        if ($normalizedCatalogId.Length -ge 3 -and $wingetIdentities.Contains($normalizedCatalogId)) { $isInstalled = $true }
        if (-not $isInstalled -and $normalizedChocoId.Length -ge 3 -and $chocoIdentities.Contains($normalizedChocoId)) { $isInstalled = $true }
        if (-not $isInstalled) {
            foreach ($candidate in $candidateIdentities) {
                if ($scoopIdentities.Contains($candidate)) { $isInstalled = $true; break }
            }
        }

        # Windows registry and AppX identities, using exact normalized matches first.
        if (-not $isInstalled) {
            foreach ($normalized in $candidateIdentities) {
                if ($installedIdentities.Contains($normalized)) { $isInstalled = $true; break }
                # Accept only a version/architecture suffix after a complete known identity.
                foreach ($observed in $installedIdentities) {
                    if ($observed.Length -gt $normalized.Length -and $observed.StartsWith($normalized, [System.StringComparison]::OrdinalIgnoreCase)) {
                        $suffix = $observed.Substring($normalized.Length)
                        if ($suffix -match '^\d+(x64|x86|64bit|32bit)?$') { $isInstalled = $true; break }
                    }
                }
                if ($isInstalled) { break }
            }
        }

        # Fallback for WinGet CLI versions whose table headings/layout differ.
        if (-not $isInstalled -and -not [string]::IsNullOrWhiteSpace($wingetRawOutput) -and -not [string]::IsNullOrWhiteSpace([string]$app.Id)) {
            $escapedId = [regex]::Escape([string]$app.Id)
            if ($wingetRawOutput -match ('(?im)(?<![A-Za-z0-9_.-])' + $escapedId + '(?![A-Za-z0-9_.-])')) { $isInstalled = $true }
        }

        $app.IsInstalled = $isInstalled
        if ($isInstalled) { $installedCount++ }
    }

    Write-AMRLog ("Installed inventory scanned: {0} registry entries, {1} AppX/MSIX packages, {2} WinGet IDs, {3} Chocolatey packages, {4} Scoop apps. Catalog matches: {5}." -f $registryEntryCount,$appxPackageCount,$wingetIdentities.Count,$chocoIdentities.Count,$scoopIdentities.Count,$installedCount) INFO Software
    return $installedCount
}


# ----------------------------------------------------------
# Background installed-inventory scanner
# The inventory scan runs in a dedicated runspace. Only the
# final IsInstalled flags are copied back on the WPF UI thread.
# ----------------------------------------------------------
$script:InstalledScanState = @{
    Current = $null
    Ready = $false
    Count = 0
    Error = ''
    PendingShow = $false
    RescanRequested = $false
}

function Set-AMRInstalledViewVisible {
    param([int]$InstalledCount)

    $script:ShowInstalledOnly = $true
    (C 'ShowInstalledBtn').Content = "Show All ($InstalledCount)"
    (C 'ShowInstalledBtn').ToolTip = 'Return to the full software catalog.'
    (C 'ShowInstalledBtn').IsEnabled = $true
    (C 'UninstallSelectedBtn').Visibility = 'Visible'
    Update-AMRSoftwareCategoryCounts
    $script:AppsView.Refresh()
    Write-AMRLog "Installed-app filter enabled: $InstalledCount catalog application(s) detected." INFO Software
}

function Complete-AMRInstalledCatalogScan {
    param($JobState)

    $job = $JobState.Current
    if (-not $job) { return }

    $outputItems = @()
    $workerError = ''
    try {
        $outputItems = @($job.PowerShell.EndInvoke($job.AsyncResult))
    } catch {
        $workerError = $_.Exception.Message
    }

    if (-not $workerError -and $job.PowerShell.Streams.Error.Count -gt 0) {
        $workerError = (($job.PowerShell.Streams.Error | ForEach-Object { $_.ToString() }) -join "`n")
    }

    $payload = $null
    foreach ($outputItem in $outputItems) {
        if ($null -ne $outputItem -and $outputItem.PSObject.Properties['InstalledFlags']) {
            $payload = $outputItem
        }
    }
    if (-not $payload -and -not $workerError) {
        $workerError = 'The background inventory worker completed without returning a valid result.'
    }

    try { $job.PowerShell.Dispose() } catch {}
    try { $job.Runspace.Close(); $job.Runspace.Dispose() } catch {}
    $JobState.Current = $null

    if ($payload -and -not $workerError) {
        $flags = @($payload.InstalledFlags)
        if ($flags.Count -ne $script:SoftwareCatalog.Count) {
            $workerError = "Inventory result size mismatch. Expected $($script:SoftwareCatalog.Count), received $($flags.Count)."
        } else {
            for ($index = 0; $index -lt $script:SoftwareCatalog.Count; $index++) {
                $script:SoftwareCatalog[$index].IsInstalled = [bool]$flags[$index]
            }
            $JobState.Ready = $true
            $JobState.Count = [int]$payload.Count
            $JobState.Error = ''
            foreach ($entry in @($payload.Logs)) {
                if ($entry -and $entry.Message) {
                    $level = if ($entry.Level) { [string]$entry.Level } else { 'INFO' }
                    $area = if ($entry.Area) { [string]$entry.Area } else { 'Software' }
                    Write-AMRLog ([string]$entry.Message) $level $area
                }
            }
        }
    }

    if ($workerError) {
        $JobState.Ready = $false
        $JobState.Error = $workerError
        Write-AMRLog "Background installed-app scan failed: $workerError" ERROR Software
        if ($JobState.PendingShow) {
            (C 'ShowInstalledBtn').Content = 'Show Installed'
            (C 'ShowInstalledBtn').IsEnabled = $true
            $JobState.PendingShow = $false
            Show-AMRMessage "Could not finish the installed-app scan:`n`n$workerError" 'Installed Apps Scan' OK Error | Out-Null
        }
    }

    # If a refresh was requested while an older scan was running (for example,
    # immediately after uninstall), run a fresh scan before publishing the view.
    if ($JobState.RescanRequested) {
        $JobState.RescanRequested = $false
        $JobState.Ready = $false
        Start-AMRInstalledCatalogScan -ShowWhenReady:([bool]$JobState.PendingShow)
        return
    }

    if ($JobState.Ready -and $JobState.PendingShow) {
        $JobState.PendingShow = $false
        Set-AMRInstalledViewVisible -InstalledCount $JobState.Count
    }
}

function Start-AMRInstalledCatalogScan {
    param(
        [switch]$ShowWhenReady,
        [switch]$Refresh
    )

    $state = $script:InstalledScanState
    if ($ShowWhenReady) { $state.PendingShow = $true }

    if ($state.Current) {
        if ($Refresh) { $state.RescanRequested = $true }
        return
    }

    if ($state.Ready -and -not $Refresh) {
        if ($state.PendingShow) {
            $state.PendingShow = $false
            Set-AMRInstalledViewVisible -InstalledCount $state.Count
        }
        return
    }

    $catalogSnapshot = @(
        foreach ($app in $script:SoftwareCatalog) {
            [pscustomobject]@{
                Name = [string]$app.Name
                Id = [string]$app.Id
                ChocoId = [string]$app.ChocoId
                IsInstalled = $false
            }
        }
    )

    try {
        $inventoryCommand = Get-Command Update-AMRInstalledCatalogState -ErrorAction Stop
        $inventoryFunctionBody = $inventoryCommand.ScriptBlock.ToString()

        $workerScript = @'
param($CatalogSnapshot, $InventoryFunctionBody)
$ErrorActionPreference = 'Continue'
$script:SoftwareCatalog = @($CatalogSnapshot)
$script:InventoryLogs = New-Object 'System.Collections.Generic.List[object]'
function Write-AMRLog {
    param([string]$Message, [string]$Level, [string]$Area)
    try {
        [void]$script:InventoryLogs.Add([pscustomobject]@{
            Message = [string]$Message
            Level = [string]$Level
            Area = [string]$Area
        })
    } catch {}
}
$definition = "function Update-AMRInstalledCatalogState {`r`n" + $InventoryFunctionBody + "`r`n}"
Invoke-Expression $definition
$count = Update-AMRInstalledCatalogState
$flags = @($script:SoftwareCatalog | ForEach-Object { [bool]$_.IsInstalled })
[pscustomobject]@{
    Count = [int]$count
    InstalledFlags = $flags
    Logs = @($script:InventoryLogs.ToArray())
}
'@

        $runspace = [System.Management.Automation.Runspaces.RunspaceFactory]::CreateRunspace()
        $runspace.Open()
        $powerShell = [PowerShell]::Create()
        $powerShell.Runspace = $runspace
        [void]$powerShell.AddScript($workerScript)
        [void]$powerShell.AddArgument($catalogSnapshot)
        [void]$powerShell.AddArgument($inventoryFunctionBody)
        $asyncResult = $powerShell.BeginInvoke()

        $timer = New-Object System.Windows.Threading.DispatcherTimer
        $timer.Interval = [TimeSpan]::FromMilliseconds(150)
        $jobState = $state
        $job = [pscustomobject]@{
            PowerShell = $powerShell
            Runspace = $runspace
            AsyncResult = $asyncResult
            Timer = $timer
        }
        $state.Current = $job

        $timer.Add_Tick({
            $activeJob = $jobState.Current
            if (-not $activeJob) {
                $timer.Stop()
                return
            }
            if (-not $activeJob.AsyncResult.IsCompleted) { return }
            $timer.Stop()
            Complete-AMRInstalledCatalogScan -JobState $jobState
        }.GetNewClosure())

        $timer.Start()
        Write-AMRLog 'Installed-app inventory scan started in the background. The interface remains available.' INFO Software
    } catch {
        $state.Error = $_.Exception.Message
        $state.Ready = $false
        $state.Current = $null
        (C 'ShowInstalledBtn').Content = 'Show Installed'
        (C 'ShowInstalledBtn').IsEnabled = $true
        Write-AMRLog "Could not start the background installed-app scan: $($_.Exception.Message)" ERROR Software
        if ($state.PendingShow) {
            $state.PendingShow = $false
            Show-AMRMessage "Could not start the installed-app scan:`n`n$($_.Exception.Message)" 'Installed Apps Scan' OK Error | Out-Null
        }
    }
}

$script:AppsView.Filter = [System.Predicate[object]]{
    param($item)
    if ($script:ShowInstalledOnly -and -not $item.IsInstalled) { return $false }

    $selectedCategory = [string]$script:SelectedSoftwareCategory
    if (-not [string]::IsNullOrWhiteSpace($selectedCategory) -and
        $selectedCategory -ne 'All Applications' -and
        [string]$item.Category -ne $selectedCategory) { return $false }

    $searchText = (C 'SearchBox').Text
    if ([string]::IsNullOrWhiteSpace($searchText)) { return $true }
    $escaped = [regex]::Escape($searchText)
    return ($item.Name -match "(?i)$escaped") -or ($item.Id -match "(?i)$escaped")
}

(C 'SoftwareCategoryList').Add_SelectionChanged({
    $selected = (C 'SoftwareCategoryList').SelectedItem
    if ($null -ne $selected) {
        $script:SelectedSoftwareCategory = [string]$selected.Name
        $script:AppsView.Refresh()
    }
})

(C 'SearchBox').Add_TextChanged({ $script:AppsView.Refresh() })
(C 'ShowInstalledBtn').Add_Click({
    if (-not $script:ShowInstalledOnly) {
        if ($script:InstalledScanState.Ready) {
            Set-AMRInstalledViewVisible -InstalledCount $script:InstalledScanState.Count
        } else {
            (C 'ShowInstalledBtn').Content = 'Loading Installed...'
            (C 'ShowInstalledBtn').IsEnabled = $false
            $script:ProgressText.Text = 'Preparing installed applications in the background...'
            Start-AMRInstalledCatalogScan -ShowWhenReady
        }
    } else {
        $script:ShowInstalledOnly = $false
        (C 'ShowInstalledBtn').Content = 'Show Installed'
        (C 'ShowInstalledBtn').ToolTip = 'Show only applications detected as installed on this PC.'
        (C 'ShowInstalledBtn').IsEnabled = $true
        (C 'UninstallSelectedBtn').Visibility = 'Collapsed'
        Update-AMRSoftwareCategoryCounts
        $script:AppsView.Refresh()
        Write-AMRLog 'Installed-app filter disabled; showing the full software catalog.' INFO Software
    }
})
(C 'SoftwareGrid').ItemsSource = $script:AppsView

# Keep the software catalog responsive: 3 cards in the normal window and 4 when maximized.
function Find-AMRVisualChildByType {
    param(
        [System.Windows.DependencyObject]$Parent,
        [type]$ChildType
    )
    if ($null -eq $Parent) { return $null }
    $count = [System.Windows.Media.VisualTreeHelper]::GetChildrenCount($Parent)
    for ($i = 0; $i -lt $count; $i++) {
        $child = [System.Windows.Media.VisualTreeHelper]::GetChild($Parent, $i)
        if ($ChildType.IsAssignableFrom($child.GetType())) { return $child }
        $found = Find-AMRVisualChildByType -Parent $child -ChildType $ChildType
        if ($null -ne $found) { return $found }
    }
    return $null
}

$script:UpdateSoftwareGridColumns = {
    $uniformGrid = Find-AMRVisualChildByType -Parent (C 'SoftwareGrid') -ChildType ([System.Windows.Controls.Primitives.UniformGrid])
    if ($null -ne $uniformGrid) {
        $uniformGrid.Columns = if ($script:Window.WindowState -eq [System.Windows.WindowState]::Maximized) { 4 } else { 3 }
    }
}
$script:Window.Add_Loaded({ & $script:UpdateSoftwareGridColumns })
$script:Window.Add_StateChanged({ & $script:UpdateSoftwareGridColumns })

(C 'DeselectAllBtn').Add_Click({
    if ($script:InstallRunning) {
        Write-AMRLog "Cannot clear selection while an installation queue is running." WARNING Software
        return
    }
    foreach ($app in $script:SoftwareCatalog) { $app.IsSelected = $false }
    $script:AppsView.Refresh()
    Write-AMRLog "Cleared app selections." INFO Software
})

# Shared engine state
$script:InstallRunning = $false
$script:InstallPowerShell = $null
$script:InstallRunspace = $null
$script:InstallAsyncResult = $null
$script:InstallOutput = $null
$script:InstallResultQueue = $null
$script:InstallCompletionFile = $null
$script:InstallLogQueue = New-Object 'System.Collections.Concurrent.ConcurrentQueue[string]'
$script:InstallTimer = $null
$script:InstallActionName = ''
$script:InstallSelectedSnapshot = @()

# Worker code runs in dedicated Runspace & reports progress
$script:InstallWorkerCode = @'
param(
    [object[]]$Apps,
    [string]$ActionCommand,
    [string]$ActionName,
    [bool]$Interactive,
    [string]$DownloadDir,
    [System.Collections.Concurrent.ConcurrentQueue[string]]$LogQueue,
    [string]$CompletionFilePath
)

$ErrorActionPreference = "Stop"
$script:ChocoCheckedPath = $null

function Write-WorkerLog {
    param([string]$Message, [string]$Level = "INFO", [int]$Percent = -1)
    $stamp = Get-Date -Format "yyyy-MM-dd HH:mm:ss.fff"
    $pctPrefix = if ($Percent -ge 0) { "PROG:$Percent|" } else { "" }
    [void]$LogQueue.Enqueue("${pctPrefix}[$stamp] [$Level] [Software] $Message")
}

# Last-resort worker trap: preserve the original terminating error and publish a
# diagnostic completion record instead of losing the runspace failure silently.
trap {
    $fatalRecord = $_
    $fatalMessage = [string]$fatalRecord.Exception.Message
    $fatalType = [string]$fatalRecord.Exception.GetType().FullName
    $fatalStack = [string]$fatalRecord.ScriptStackTrace
    if ([string]::IsNullOrWhiteSpace($fatalMessage)) { $fatalMessage = [string]$fatalRecord }
    try { Write-WorkerLog ("WORKER-FATAL | Type={0} | Error={1} | Stack={2}" -f $fatalType,$fatalMessage,$fatalStack) 'ERROR' } catch {}
    try {
        $fatalResults = @()
        if (Get-Variable -Name results -Scope 0 -ErrorAction SilentlyContinue) { $fatalResults = $results.ToArray() }
        $fatalSummary = [pscustomobject]@{
            ActionName = [string]$ActionName
            SuccessCount = if (Get-Variable successCount -Scope 0 -ErrorAction SilentlyContinue) { [int]$successCount } else { 0 }
            UnverifiedCount = if (Get-Variable unverifiedCount -Scope 0 -ErrorAction SilentlyContinue) { [int]$unverifiedCount } else { 0 }
            CancelledCount = if (Get-Variable cancelledCount -Scope 0 -ErrorAction SilentlyContinue) { [int]$cancelledCount } else { 0 }
            FailedCount = if (Get-Variable failedCount -Scope 0 -ErrorAction SilentlyContinue) { [int]$failedCount } else { 1 }
            SkippedCount = if (Get-Variable skippedCount -Scope 0 -ErrorAction SilentlyContinue) { [int]$skippedCount } else { 0 }
            RebootNeeded = $false
            Results = $fatalResults
            WorkerError = $fatalMessage
            WorkerErrorType = $fatalType
            WorkerStackTrace = $fatalStack
        }
        $fatalJson = ConvertTo-Json -InputObject $fatalSummary -Depth 8 -Compress
        if (-not [string]::IsNullOrWhiteSpace($CompletionFilePath)) {
            $fatalTemp = $CompletionFilePath + '.fatal.' + [guid]::NewGuid().ToString('N')
            $fatalEncoding = New-Object System.Text.UTF8Encoding($false)
            [System.IO.File]::WriteAllText($fatalTemp, [string]$fatalJson, $fatalEncoding)
            if ([System.IO.File]::Exists($CompletionFilePath)) { [System.IO.File]::Delete($CompletionFilePath) }
            [System.IO.File]::Move($fatalTemp, $CompletionFilePath)
        }
    } catch {
        try { Write-WorkerLog ("WORKER-FATAL-PUBLISH-ERROR | {0}" -f $_.Exception.Message) 'ERROR' } catch {}
    }
    break
}

function Normalize-WorkerIdentity {
    param([string]$Value)
    if ([string]::IsNullOrWhiteSpace($Value)) { return '' }
    return (($Value -replace '[^a-zA-Z0-9]', '').ToLowerInvariant())
}

function Invoke-WorkerCapture {
    param([string]$FilePath,[string[]]$ArgumentList,[ValidateRange(1,7200)][int]$TimeoutSeconds=15)
    $token=[guid]::NewGuid().ToString('N')
    $stdoutPath=Join-Path ([IO.Path]::GetTempPath()) ("AMR_SW_{0}.out" -f $token)
    $stderrPath=Join-Path ([IO.Path]::GetTempPath()) ("AMR_SW_{0}.err" -f $token)
    $process=$null; $startedAt=Get-Date
    try {
        $quotedArguments = foreach ($argument in $ArgumentList) {
            $argument = [string]$argument
            if ($argument.Length -eq 0 -or $argument -match '[\s"]') {
                $escaped = [regex]::Replace($argument, '(\\*)"', '$1$1\"')
                $escaped = [regex]::Replace($escaped, '(\\+)$', '$1$1')
                '"' + $escaped + '"'
            } else { $argument }
        }
        $argumentLine = ($quotedArguments -join ' ')
        $params=@{FilePath=$FilePath;ArgumentList=$argumentLine;PassThru=$true;RedirectStandardOutput=$stdoutPath;RedirectStandardError=$stderrPath;WindowStyle='Hidden';ErrorAction='Stop'}
        $process=Start-Process @params
        if (-not $process.WaitForExit($TimeoutSeconds*1000)) {
            Write-WorkerLog ("[Capture] {0} PID={1} timed out after {2}s." -f $FilePath,$process.Id,$TimeoutSeconds) 'WARNING'
            try { $null = & "$env:SystemRoot\System32\taskkill.exe" /PID $process.Id /T /F 2>&1; $null=$process.WaitForExit(5000) } catch { try {$process.Kill();[void]$process.WaitForExit(3000)}catch{} }
            return [pscustomobject]@{ExitCode=-2;TimedOut=$true;Output='';Error='Process timed out.';ProcessId=$process.Id;ElapsedSeconds=[math]::Round(((Get-Date)-$startedAt).TotalSeconds,1)}
        }
        $process.WaitForExit(); $process.Refresh()
        $out=if(Test-Path -LiteralPath $stdoutPath){Get-Content -LiteralPath $stdoutPath -Raw -ErrorAction SilentlyContinue}else{''}
        $err=if(Test-Path -LiteralPath $stderrPath){Get-Content -LiteralPath $stderrPath -Raw -ErrorAction SilentlyContinue}else{''}
        return [pscustomobject]@{ExitCode=[int]$process.ExitCode;TimedOut=$false;Output=[string]$out;Error=[string]$err;ProcessId=$process.Id;ElapsedSeconds=[math]::Round(((Get-Date)-$startedAt).TotalSeconds,1)}
    } catch {return [pscustomobject]@{ExitCode=-1;TimedOut=$false;Output='';Error=$_.Exception.Message;ProcessId=-1;ElapsedSeconds=[math]::Round(((Get-Date)-$startedAt).TotalSeconds,1)}}
    finally {if($process){try{$process.Dispose()}catch{}};foreach($f in @($stdoutPath,$stderrPath)){if(Test-Path -LiteralPath $f){Remove-Item -LiteralPath $f -Force -ErrorAction SilentlyContinue}}}
}

function Test-WorkerInstalled {
    param(
        [string]$AppName,
        [string]$AppId = '',
        [string]$ChocoId = '',
        [switch]$SkipWinget
    )

    if ([string]::IsNullOrWhiteSpace($AppName) -and [string]::IsNullOrWhiteSpace($AppId)) { return $false }
    $cleanTarget = Normalize-WorkerIdentity $AppName
    $cleanId = Normalize-WorkerIdentity $AppId
    $cleanChoco = Normalize-WorkerIdentity $ChocoId

    # Keep worker-side identity matching consistent with the Show Installed catalog
    # filter. Registry display names frequently differ from catalog labels (for
    # example, catalog "Everything Search" vs. uninstall entry "Everything 1.4.x").
    $identityCandidates = New-Object 'System.Collections.Generic.List[string]'
    foreach ($identity in @($cleanTarget, $cleanId, $cleanChoco)) {
        if (-not [string]::IsNullOrWhiteSpace($identity) -and -not $identityCandidates.Contains($identity)) {
            $identityCandidates.Add($identity)
        }
    }
    $workerIdentityAliases = @{
        'everythingsearch' = @('everything')
        'visualstudiocode' = @('vscode')
        'microsoftedgewebview2runtime' = @('webview2runtime','microsoftedgewebview2')
        'vlcmediaplayer' = @('vlc')
        'sumatrapdf' = @('sumatrapdf')
        'sharex' = @('sharex')
    }
    foreach ($baseIdentity in @($identityCandidates.ToArray())) {
        if ($workerIdentityAliases.ContainsKey($baseIdentity)) {
            foreach ($alias in $workerIdentityAliases[$baseIdentity]) {
                $normalizedAlias = Normalize-WorkerIdentity ([string]$alias)
                if ($normalizedAlias -and -not $identityCandidates.Contains($normalizedAlias)) {
                    $identityCandidates.Add($normalizedAlias)
                }
            }
        }
    }

    # 1. Exact Winget inventory check with a bounded wait.
    if (-not $SkipWinget -and -not [string]::IsNullOrWhiteSpace($AppId)) {
        $winget = Get-Command winget.exe -ErrorAction SilentlyContinue
        if ($winget) {
            $check = Invoke-WorkerCapture -FilePath $winget.Source -ArgumentList @('list','--id',$AppId,'--exact','--accept-source-agreements') -TimeoutSeconds 12
            if (-not $check.TimedOut -and $check.ExitCode -eq 0 -and $check.Output -match [regex]::Escape($AppId)) { return $true }
        }
    }

    # 2. AppX/MSIX packages. Compare exact package identity fields only.
    if (-not [string]::IsNullOrWhiteSpace($AppId)) {
        try {
            $appx = @(Get-AppxPackage -ErrorAction SilentlyContinue | Where-Object {
                $_.Name -ieq $AppId -or $_.PackageFamilyName -ieq $AppId
            })
            if ($appx.Count -gt 0) { return $true }
        } catch {}
    }

    # 3. Both registry views and both user/machine uninstall hives.
    $paths = @(
        'HKLM:\Software\Microsoft\Windows\CurrentVersion\Uninstall\*',
        'HKLM:\Software\Wow6432Node\Microsoft\Windows\CurrentVersion\Uninstall\*',
        'HKCU:\Software\Microsoft\Windows\CurrentVersion\Uninstall\*',
        'HKCU:\Software\Wow6432Node\Microsoft\Windows\CurrentVersion\Uninstall\*'
    )
    foreach ($path in $paths) {
        try {
            foreach ($item in @(Get-ItemProperty -Path $path -ErrorAction SilentlyContinue)) {
                $displayNameProperty = $item.PSObject.Properties['DisplayName']
                $childNameProperty = $item.PSObject.Properties['PSChildName']
                $displayName = if ($displayNameProperty) { [string]$displayNameProperty.Value } else { '' }
                $childName = if ($childNameProperty) { [string]$childNameProperty.Value } else { '' }
                $candidate = Normalize-WorkerIdentity $displayName
                $candidateChild = Normalize-WorkerIdentity $childName
                foreach ($expectedIdentity in $identityCandidates) {
                    if ([string]::IsNullOrWhiteSpace($expectedIdentity)) { continue }
                    foreach ($observedIdentity in @($candidate, $candidateChild)) {
                        if ([string]::IsNullOrWhiteSpace($observedIdentity)) { continue }
                        if ($observedIdentity -eq $expectedIdentity) { return $true }
                        # Accept version/architecture suffixes only after a complete
                        # known identity, never arbitrary partial-name matches.
                        if ($observedIdentity.Length -gt $expectedIdentity.Length -and
                            $observedIdentity.StartsWith($expectedIdentity, [StringComparison]::OrdinalIgnoreCase)) {
                            $suffix = $observedIdentity.Substring($expectedIdentity.Length)
                            if ($suffix -match '^\d+(x64|x86|64bit|32bit)?$') { return $true }
                        }
                    }
                }
            }
        } catch {}
    }
    return $false
}

function Wait-WorkerInstalled {
    param([string]$AppName,[string]$AppId='',[string]$ChocoId='',[int]$TimeoutSeconds=45,[int]$PollSeconds=3)
    if (Test-WorkerInstalled -AppName $AppName -AppId $AppId -ChocoId $ChocoId) { return $true }
    $deadline=(Get-Date).AddSeconds([Math]::Max(1,$TimeoutSeconds))
    do {
        if (Test-WorkerInstalled -AppName $AppName -AppId $AppId -ChocoId $ChocoId -SkipWinget) { return $true }
        Start-Sleep -Seconds ([Math]::Max(1,$PollSeconds))
    } while ((Get-Date) -lt $deadline)
    return (Test-WorkerInstalled -AppName $AppName -AppId $AppId -ChocoId $ChocoId -SkipWinget)
}

function Resolve-WorkerWingetId {
    param([string]$AppName, [string]$ConfiguredId)

    $winget = Get-Command winget.exe -ErrorAction SilentlyContinue
    if (-not $winget) { return $ConfiguredId }

    # First trust the catalog ID when Winget can see that exact installed package.
    if (-not [string]::IsNullOrWhiteSpace($ConfiguredId)) {
        try {
            $byId = Invoke-WorkerCapture -FilePath $winget.Source -ArgumentList @('list','--id',$ConfiguredId,'--exact','--accept-source-agreements') -TimeoutSeconds 20
            if (-not $byId.TimedOut -and $byId.ExitCode -eq 0 -and $byId.Output -match [regex]::Escape($ConfiguredId)) { return $ConfiguredId }
        } catch {}
    }

    # Catalog IDs can change or differ from the ID used by an already-installed package.
    # Resolve the exact display name to the installed Winget ID before upgrade/repair.
    if ([string]::IsNullOrWhiteSpace($AppName)) { return $ConfiguredId }
    try {
        $listedResult = Invoke-WorkerCapture -FilePath $winget.Source -ArgumentList @('list','--name',$AppName,'--exact','--accept-source-agreements') -TimeoutSeconds 20
        if (-not $listedResult.TimedOut -and $listedResult.ExitCode -eq 0) {
            foreach ($line in @($listedResult.Output -split "`r?`n")) {
                $text = ([string]$line).Trim()
                # Winget table columns can be separated by only one space when a name fills its column.
                # Since --name --exact was used, parse the ID immediately after the exact display name.
                if ($text.StartsWith($AppName.Trim(), [StringComparison]::OrdinalIgnoreCase)) {
                    $tail = $text.Substring($AppName.Trim().Length).TrimStart()
                    $columns = @($tail -split '\s+')
                    if ($columns.Count -ge 2 -and $columns[0] -and $columns[0] -notin @('Id','Version')) {
                        Write-WorkerLog "Resolved installed Winget ID for ${AppName}: $($columns[0])" "INFO"
                        return [string]$columns[0]
                    }
                }
            }
        }
    } catch {}
    return $ConfiguredId
}

function Invoke-WorkerMsiRepair {
    param([string]$AppName, [bool]$Interactive, [int]$BasePercent, [ValidateRange(30,7200)][int]$TimeoutSeconds = 1800)

    $paths = @(
        "HKLM:\Software\Microsoft\Windows\CurrentVersion\Uninstall\*",
        "HKLM:\Software\Wow6432Node\Microsoft\Windows\CurrentVersion\Uninstall\*",
        "HKCU:\Software\Microsoft\Windows\CurrentVersion\Uninstall\*"
    )
    $entry = $null
    try {
        $entry = Get-ItemProperty -Path $paths -ErrorAction SilentlyContinue |
            Where-Object {
                $nameProperty = $_.PSObject.Properties['DisplayName']
                $installerProperty = $_.PSObject.Properties['WindowsInstaller']
                $nameValue = if ($nameProperty) { [string]$nameProperty.Value } else { '' }
                $installerValue = if ($installerProperty) { $installerProperty.Value } else { 0 }
                (-not [string]::IsNullOrWhiteSpace($nameValue)) -and
                ($nameValue.Trim() -ieq $AppName.Trim()) -and
                ([int]$installerValue -eq 1)
            } |
            Select-Object -First 1
    } catch {}

    if (-not $entry) { return $null }
    $productCode = $null
    $candidate = [string]$entry.UninstallString
    if ($candidate -match '(?i)\{[0-9a-f]{8}-(?:[0-9a-f]{4}-){3}[0-9a-f]{12}\}') {
        $productCode = $Matches[0]
    } elseif ([string]$entry.PSChildName -match '^\{[0-9a-fA-F-]{36}\}$') {
        $productCode = [string]$entry.PSChildName
    }
    if (-not $productCode) { return $null }

    $args = @('/fa', $productCode)
    if (-not $Interactive) { $args += @('/qn', '/norestart') }
    Write-WorkerLog "[MSI Repair] Running native Windows Installer repair for $AppName ($productCode)." "INFO" -Percent ($BasePercent + 10)
    try {
        $proc = Invoke-ProcessResult -FilePath 'msiexec.exe' -ArgumentList $args -ShowWindow:$Interactive -TimeoutSeconds $TimeoutSeconds
        $ok = Test-ExitSuccess -ExitCode $proc.ExitCode
        return [pscustomobject]@{ Success=$ok; ExitCode=$proc.ExitCode; Started=$true; Reboot=($proc.ExitCode -in @(1641,3010)) }
    } catch {
        Write-WorkerLog "[MSI Repair] $AppName failed: $_" "WARNING" -Percent $BasePercent
        return [pscustomobject]@{ Success=$false; ExitCode=-1; Started=$true; Reboot=$false }
    }
}

function Get-ChocoPath {
    if ($script:ChocoCheckedPath -and (Test-Path -LiteralPath $script:ChocoCheckedPath)) {
        return $script:ChocoCheckedPath
    }

    $command = Get-Command choco.exe -ErrorAction SilentlyContinue
    if ($command) {
        $script:ChocoCheckedPath = $command.Source
        return $script:ChocoCheckedPath
    }

    $defaultPath = Join-Path $env:ProgramData "chocolatey\bin\choco.exe"
    if (Test-Path -LiteralPath $defaultPath) {
        $script:ChocoCheckedPath = $defaultPath
        return $script:ChocoCheckedPath
    }
    return $null
}

function Ensure-Chocolatey {
    $existing = Get-ChocoPath
    if ($existing) { return $existing }

    Write-WorkerLog "Chocolatey is missing; attempting one-time initialization." "WARNING"
    $setupFile = Join-Path $DownloadDir ("choco_setup_{0}.ps1" -f [guid]::NewGuid().ToString("N"))

    try {
        [Net.ServicePointManager]::SecurityProtocol =
            [Net.ServicePointManager]::SecurityProtocol -bor [Net.SecurityProtocolType]::Tls12

        Invoke-WebRequest -Uri "https://community.chocolatey.org/install.ps1" `
            -OutFile $setupFile -UseBasicParsing -ErrorAction Stop

        if (!(Test-Path -LiteralPath $setupFile) -or (Get-Item -LiteralPath $setupFile).Length -lt 1000) {
            throw "Chocolatey bootstrap script is missing or incomplete."
        }

        Write-WorkerLog '[Chocolatey] Running official bootstrap with a 15-minute execution limit.' 'INFO'
        $process = Invoke-ProcessResult -FilePath 'powershell.exe' `
            -ArgumentList @('-NoProfile', '-ExecutionPolicy', 'Bypass', '-File', "`"$setupFile`"") `
            -ShowWindow:$false -TimeoutSeconds 900

        $machinePath = [Environment]::GetEnvironmentVariable('Path', 'Machine')
        $userPath = [Environment]::GetEnvironmentVariable('Path', 'User')
        $env:Path = "$machinePath;$userPath"

        $found = Get-ChocoPath
        if (-not $process.TimedOut -and $process.ExitCode -eq 0 -and $found) {
            Write-WorkerLog "Chocolatey initialized successfully." "SUCCESS"
            return $found
        }

        $failureReason = if ($process.TimedOut) { 'timed out after 900 seconds' } else { "exit code $($process.ExitCode)" }
        throw "Chocolatey setup failed ($failureReason); choco.exe was not verified."
    }
    catch {
        Write-WorkerLog "Chocolatey initialization error: $_" "ERROR"
        return $null
    }
    finally {
        if (Test-Path -LiteralPath $setupFile) {
            Remove-Item -LiteralPath $setupFile -Force -ErrorAction SilentlyContinue
        }
    }
}

function Invoke-ProcessResult {
    param(
        [string]$FilePath,
        [string[]]$ArgumentList,
        [bool]$ShowWindow,
        [ValidateRange(30,7200)][int]$TimeoutSeconds = 1800
    )

    $process = $null
    $startedAt = Get-Date
    try {
        $startParams = @{
            FilePath = $FilePath
            ArgumentList = $ArgumentList
            PassThru = $true
            ErrorAction = 'Stop'
        }
        if (-not $ShowWindow) { $startParams['WindowStyle'] = 'Hidden' }
        $process = Start-Process @startParams
        Write-WorkerLog ("[Process] Started PID={0}; File={1}; Timeout={2}s." -f $process.Id,$FilePath,$TimeoutSeconds) 'INFO'
        $exited = $process.WaitForExit($TimeoutSeconds * 1000)
        if (-not $exited) {
            Write-WorkerLog ("[Process] PID={0} exceeded {1}s; attempting process-tree termination." -f $process.Id,$TimeoutSeconds) 'ERROR'
            try {
                $null = & "$env:SystemRoot\System32\taskkill.exe" /PID $process.Id /T /F 2>&1
                $null = $process.WaitForExit(10000)
                if (-not $process.HasExited) { $process.Kill(); [void]$process.WaitForExit(5000) }
            } catch {
                try { if (-not $process.HasExited) { $process.Kill(); [void]$process.WaitForExit(5000) } } catch {}
            }
            return [pscustomobject]@{
                ExitCode = -2; TimedOut = $true; ProcessId = $process.Id
                FilePath = $FilePath; ElapsedSeconds = [math]::Round(((Get-Date)-$startedAt).TotalSeconds,1)
            }
        }
        $process.Refresh()
        return [pscustomobject]@{
            ExitCode = [int]$process.ExitCode; TimedOut = $false; ProcessId = $process.Id
            FilePath = $FilePath; ElapsedSeconds = [math]::Round(((Get-Date)-$startedAt).TotalSeconds,1)
        }
    } catch {
        Write-WorkerLog ("[Process] Could not execute '{0}': {1}" -f $FilePath,$_.Exception.Message) 'ERROR'
        return [pscustomobject]@{
            ExitCode = -1; TimedOut = $false; ProcessId = $(if ($process) {$process.Id} else {-1})
            FilePath = $FilePath; ElapsedSeconds = [math]::Round(((Get-Date)-$startedAt).TotalSeconds,1)
        }
    } finally {
        if ($process) { try { $process.Dispose() } catch {} }
    }
}

function Test-ExitSuccess {
    param([int]$ExitCode)
    return ($ExitCode -in @(0, 1641, 3010))
}

function Invoke-WingetUnelevated {
    param(
        [string]$WingetPath,
        [string[]]$Arguments,
        [bool]$ShowWindow = $false,
        [int]$TimeoutSeconds = 1800
    )

    $tempRoot = [IO.Path]::GetTempPath()
    $jobId = [guid]::NewGuid().ToString('N')
    $helperPath = Join-Path $tempRoot ("AMR_Winget_UserContext_{0}.ps1" -f $jobId)
    $payloadPath = Join-Path $tempRoot ("AMR_Winget_UserContext_{0}.json" -f $jobId)
    $resultPath = Join-Path $tempRoot ("AMR_Winget_UserContext_{0}.exit" -f $jobId)
    $pidPath = Join-Path $tempRoot ("AMR_Winget_UserContext_{0}.pid" -f $jobId)
    $helperCode = @"
param([Parameter(Mandatory=`$true)][string]`$PayloadPath, [Parameter(Mandatory=`$true)][string]`$ResultPath, [Parameter(Mandatory=`$true)][string]`$PidPath)
`$exitCode = -1
try {
    `$payload = Get-Content -LiteralPath `$PayloadPath -Raw -ErrorAction Stop | ConvertFrom-Json -ErrorAction Stop
    `$identity = [Security.Principal.WindowsIdentity]::GetCurrent()
    `$principal = New-Object -TypeName Security.Principal.WindowsPrincipal -ArgumentList `$identity
    if (`$principal.IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)) { throw 'Explorer helper is still elevated; refusing to run an elevation-prohibited installer.' }
    [IO.File]::WriteAllText(`$PidPath, [string]`$PID)
    `$proc = Start-Process -FilePath ([string]`$payload.WingetPath) -ArgumentList ([string[]]`$payload.Arguments) -Wait -PassThru -NoNewWindow -ErrorAction Stop
    `$exitCode = [int]`$proc.ExitCode
} catch {
    try { [IO.File]::WriteAllText(`$ResultPath, ('ERROR: ' + `$_.Exception.Message)) } catch {}
    exit
}
try { [IO.File]::WriteAllText(`$ResultPath, [string]`$exitCode) } catch {}
"@
    $payload = [pscustomobject]@{ WingetPath=$WingetPath; Arguments=@($Arguments); ResultPath=$resultPath }
    $shell = $null
    $shellWindow = $null
    $started = $false
    try {
        Set-Content -LiteralPath $helperPath -Value $helperCode -Encoding UTF8 -ErrorAction Stop
        $payload | ConvertTo-Json -Depth 4 | Set-Content -LiteralPath $payloadPath -Encoding UTF8 -ErrorAction Stop
        $powerShellExe = Join-Path $env:WINDIR 'System32\WindowsPowerShell\v1.0\powershell.exe'
        if (-not (Test-Path -LiteralPath $powerShellExe)) { throw 'Windows PowerShell executable was not found.' }
        $parameters = '-NoProfile -ExecutionPolicy Bypass -File "{0}" -PayloadPath "{1}" -ResultPath "{2}" -PidPath "{3}"' -f $helperPath, $payloadPath, $resultPath, $pidPath
        $show = if ($ShowWindow) { 1 } else { 0 }

        # Use Explorer's shell process to launch a standard-user helper from this elevated worker.
        $shell = New-Object -ComObject Shell.Application
        try {
            $explorerWindows = @($shell.Windows() | Where-Object { $_.FullName -match '(?i)\\explorer\.exe$' })
            if ($explorerWindows.Count -gt 0) { $shellWindow = $explorerWindows[0].Application }
        } catch { $shellWindow = $null }
        if ($shellWindow) {
            [void]$shellWindow.ShellExecute($powerShellExe, $parameters, $tempRoot, 'open', $show)
        } else {
            [void]$shell.ShellExecute($powerShellExe, $parameters, $tempRoot, 'open', $show)
        }
        $started = $true

        $deadline = (Get-Date).AddSeconds($TimeoutSeconds)
        while (-not (Test-Path -LiteralPath $resultPath) -and (Get-Date) -lt $deadline) { Start-Sleep -Milliseconds 200 }
        if (-not (Test-Path -LiteralPath $resultPath)) {
            if (Test-Path -LiteralPath $pidPath) {
                $helperPid=0
                $pidText=(Get-Content -LiteralPath $pidPath -Raw -ErrorAction SilentlyContinue).Trim()
                if ([int]::TryParse($pidText,[ref]$helperPid) -and $helperPid -gt 0) {
                    Write-WorkerLog "[Winget/User] Timeout reached; terminating helper process tree PID $helperPid." 'ERROR'
                    try { $null = & "$env:SystemRoot\System32\taskkill.exe" /PID $helperPid /T /F 2>&1 } catch {}
                }
            }
            return [pscustomobject]@{ Started=$true; Success=$false; ExitCode=-1; TimedOut=$true }
        }
        $rawResult = (Get-Content -LiteralPath $resultPath -Raw -ErrorAction Stop).Trim()
        if ($rawResult -match '^ERROR:') {
            Write-WorkerLog "[Winget/User] Unelevated helper failed: $rawResult" 'ERROR'
            return [pscustomobject]@{ Started=$true; Success=$false; ExitCode=-1; TimedOut=$false }
        }
        $exitCode = -1
        if (-not [int]::TryParse($rawResult, [ref]$exitCode)) { $exitCode = -1 }
        return [pscustomobject]@{ Started=$true; Success=(Test-ExitSuccess -ExitCode $exitCode); ExitCode=$exitCode; TimedOut=$false }
    } catch {
        Write-WorkerLog "[Winget/User] Could not launch unelevated Winget: $($_.Exception.Message)" 'ERROR'
        return [pscustomobject]@{ Started=$started; Success=$false; ExitCode=-1; TimedOut=$false }
    } finally {
        if ($shellWindow) { try { [void][Runtime.InteropServices.Marshal]::ReleaseComObject($shellWindow) } catch {} }
        if ($shell) { try { [void][Runtime.InteropServices.Marshal]::ReleaseComObject($shell) } catch {} }
        foreach ($file in @($helperPath,$payloadPath,$resultPath,$pidPath)) {
            if (Test-Path -LiteralPath $file) { Remove-Item -LiteralPath $file -Force -ErrorAction SilentlyContinue }
        }
    }
}

function Install-ViaWinget {
    param(
        [string]$TargetId,
        [string]$ActionCommand,
        [string]$ExtraFlags = "",
        [bool]$Interactive = $false,
        [int]$BasePercent = 0,
        [ValidateRange(30,7200)][int]$TimeoutSeconds = 1800
    )

    $winget = Get-Command winget.exe -ErrorAction SilentlyContinue
    if (-not $winget) {
        Write-WorkerLog "Winget is unavailable." "WARNING" -Percent $BasePercent
        return [pscustomobject]@{ Success = $false; ExitCode = -1; Started = $false; Reboot = $false; FallbackSafe = $true }
    }

    $cmd = if ($ActionCommand -eq "repair") { "install" } else { $ActionCommand }
    # WhatsApp is currently distributed through the Microsoft Store source, not the community winget source.
    $wingetSource = if ($TargetId -eq '9NKSQGP7F2NH') { 'msstore' } else { 'winget' }
    Write-WorkerLog "[Winget] Using source '$wingetSource' for $TargetId." "INFO" -Percent $BasePercent
    $argumentList = @($cmd, "--id", $TargetId, "--exact",
                      "--source", $wingetSource, "--accept-source-agreements",
                      "--accept-package-agreements")

    if ($ActionCommand -eq "repair") { $argumentList += "--force" }

    if ($Interactive) {
        $argumentList += "--interactive"
    } else {
        $argumentList += @("--silent", "--disable-interactivity")
    }

    if ($ExtraFlags) {
        $argumentList += ($ExtraFlags -split "\s+" | Where-Object { $_ })
    }

    # Spotify's WinGet manifest prohibits elevation. This utility self-elevates,
    # so launch Spotify directly through Explorer's standard-user token for every action.
    if ($TargetId -eq 'Spotify.Spotify') {
        Write-WorkerLog "[Winget/User] Spotify requires a non-elevated context; launching directly as the signed-in user." "INFO" -Percent ($BasePercent + 5)
        $userResult = Invoke-WingetUnelevated -WingetPath $winget.Source -Arguments $argumentList -ShowWindow:$Interactive -TimeoutSeconds $TimeoutSeconds
        if ($userResult.Success) {
            Write-WorkerLog "[Winget/User] Spotify completed in the standard-user context (exit $($userResult.ExitCode))." "SUCCESS" -Percent ($BasePercent + 20)
            return [pscustomobject]@{ Success=$true; ExitCode=$userResult.ExitCode; Started=$true; Reboot=($userResult.ExitCode -in @(1641,3010)); FallbackSafe=$false }
        }
        $reason = if ($userResult.TimedOut) { ('timed out after {0} seconds' -f $TimeoutSeconds) } else { "failed (exit $($userResult.ExitCode))" }
        Write-WorkerLog "[Winget/User] Spotify $reason; no elevated retry or concurrent fallback will be launched." "ERROR" -Percent $BasePercent
        return [pscustomobject]@{ Success=$false; ExitCode=$userResult.ExitCode; Started=[bool]$userResult.Started; Reboot=$false; FallbackSafe=$false }
    }

    try {
        Write-WorkerLog "[Winget] Executing $cmd $TargetId" "INFO" -Percent ($BasePercent + 5)
        $proc = Invoke-ProcessResult -FilePath $winget.Source -ArgumentList $argumentList -ShowWindow:$Interactive -TimeoutSeconds $TimeoutSeconds
        $ok = Test-ExitSuccess -ExitCode $proc.ExitCode
        $reboot = ($proc.ExitCode -in @(1641, 3010))
        if ($ok) {
            Write-WorkerLog "[Winget] Completed $TargetId (exit $($proc.ExitCode))." "SUCCESS" -Percent ($BasePercent + 20)
        } elseif ($proc.ExitCode -eq -1978335146) {
            Write-WorkerLog "[Winget] $TargetId prohibits elevated execution (0x8A150056); retrying once through the user's Explorer shell." "WARNING" -Percent $BasePercent
            $userResult = Invoke-WingetUnelevated -WingetPath $winget.Source -Arguments $argumentList -ShowWindow:$Interactive -TimeoutSeconds $TimeoutSeconds
            if ($userResult.Success) {
                Write-WorkerLog "[Winget/User] Completed $TargetId in the non-elevated user context (exit $($userResult.ExitCode))." "SUCCESS" -Percent ($BasePercent + 20)
                return [pscustomobject]@{ Success=$true; ExitCode=$userResult.ExitCode; Started=$true; Reboot=($userResult.ExitCode -in @(1641,3010)); FallbackSafe=$false }
            }
            if ($userResult.TimedOut) {
                Write-WorkerLog ("[Winget/User] $TargetId exceeded the configured {0} second wait window; no fallback will be launched." -f $TimeoutSeconds) "ERROR" -Percent $BasePercent
            } else {
                Write-WorkerLog "[Winget/User] $TargetId failed in the non-elevated context (exit $($userResult.ExitCode)); no concurrent fallback will be launched." "ERROR" -Percent $BasePercent
            }
            return [pscustomobject]@{ Success=$false; ExitCode=$userResult.ExitCode; Started=$true; Reboot=$false; FallbackSafe=$false }
        } else {
            Write-WorkerLog "[Winget] Returned code $($proc.ExitCode) for $TargetId." "WARNING" -Percent $BasePercent
        }
        $fallbackSafe = (-not $proc.TimedOut) -and ($proc.ExitCode -in $wingetNotFoundOrFetchErrors)
        return [pscustomobject]@{ Success = $ok; ExitCode = $proc.ExitCode; Started = $true; Reboot = $reboot; FallbackSafe = $fallbackSafe }
    }
    catch {
        Write-WorkerLog "[Winget] Error for $TargetId : $_" "WARNING" -Percent $BasePercent
        return [pscustomobject]@{ Success = $false; ExitCode = -1; Started = $false; Reboot = $false; FallbackSafe = $true }
    }
}

function Install-ViaChocolatey {
    param(
        [string]$ChocoId,
        [ValidateSet("install", "upgrade")][string]$Action = "install",
        [bool]$Interactive = $false,
        [int]$BasePercent = 0,
        [ValidateRange(30,7200)][int]$TimeoutSeconds = 1800
    )

    if ([string]::IsNullOrWhiteSpace($ChocoId)) {
        return [pscustomobject]@{ Success = $false; ExitCode = -1; Reboot = $false; Started = $false; FallbackSafe = $true }
    }

    $choco = Ensure-Chocolatey
    if (-not $choco) {
        return [pscustomobject]@{ Success = $false; ExitCode = -1; Reboot = $false; Started = $false; FallbackSafe = $true }
    }

    $argumentList = @($Action, $ChocoId, "-y", "--no-progress")
    if (-not $Interactive) { $argumentList += "--no-color" }

    try {
        Write-WorkerLog "[Chocolatey] Executing $Action $ChocoId" "INFO" -Percent ($BasePercent + 10)
        $proc = Invoke-WorkerCapture -FilePath $choco -ArgumentList $argumentList -TimeoutSeconds $TimeoutSeconds
        $ok = (-not $proc.TimedOut) -and (Test-ExitSuccess -ExitCode $proc.ExitCode)
        $reboot = ($proc.ExitCode -in @(1641, 3010))
        $sourceUnavailable = (-not $proc.TimedOut) -and (($proc.Output + ' ' + $proc.Error) -match '(?im)(unable to find package|could not find package|package.+not found|no package found)')
        if ($ok) {
            Write-WorkerLog "[Chocolatey] Completed $ChocoId (exit $($proc.ExitCode), PID $($proc.ProcessId))." 'SUCCESS' -Percent ($BasePercent + 20)
        } else {
            $detail = (($proc.Error + ' ' + $proc.Output) -replace '\s+',' ').Trim()
            $detail = [regex]::Replace($detail,'(?i)(https?://[^\s?]+)\?[^\s]+','$1?[REDACTED]')
            if ($detail.Length -gt 500) { $detail = $detail.Substring(0,500) }
            Write-WorkerLog ("[Chocolatey] Returned code {0} for {1}; sourceUnavailable={2}; detail={3}" -f $proc.ExitCode,$ChocoId,$sourceUnavailable,$detail) 'WARNING' -Percent $BasePercent
        }
        return [pscustomobject]@{ Success = $ok; ExitCode = $proc.ExitCode; Reboot = $reboot; Started = $true; TimedOut=[bool]$proc.TimedOut; FallbackSafe=[bool]$sourceUnavailable }
    }
    catch {
        Write-WorkerLog "[Chocolatey] Error for $ChocoId : $_" "WARNING" -Percent $BasePercent
        return [pscustomobject]@{ Success = $false; ExitCode = -1; Reboot = $false; Started = $true; FallbackSafe = $false }
    }
}

function Test-InstallerSignature {
    param([string]$Path, [string]$ExpectedPublisher)

    try {
        $signature = Get-AuthenticodeSignature -FilePath $Path
        if ($signature.Status -ne "Valid") { return $false }
        if ([string]::IsNullOrWhiteSpace($ExpectedPublisher)) { return $true }
        return ($signature.SignerCertificate.Subject -like "*$ExpectedPublisher*")
    } catch {
        return $false
    }
}

function Test-WorkerAppxPublisher {
    param([string]$PackagePath,[string]$ExpectedPublisher)
    $archive=$null; $reader=$null
    try {
        Add-Type -AssemblyName System.IO.Compression.FileSystem -ErrorAction Stop
        $archive=[System.IO.Compression.ZipFile]::OpenRead($PackagePath)
        $entry=$archive.GetEntry('AppxManifest.xml')
        if(-not $entry){throw 'AppxManifest.xml was not found in the package.'}
        $entryStream=$entry.Open(); $reader=New-Object -TypeName System.IO.StreamReader -ArgumentList $entryStream
        $xml=New-Object System.Xml.XmlDocument; $xml.XmlResolver=$null; $xml.LoadXml($reader.ReadToEnd())
        $identity=$xml.SelectSingleNode("//*[local-name()='Identity']")
        if(-not $identity){throw 'Package Identity element is missing.'}
        $publisher=[string]$identity.GetAttribute('Publisher')
        if([string]::IsNullOrWhiteSpace($publisher)){throw 'Package manifest has no Publisher.'}
        if($ExpectedPublisher -and $publisher -notlike ("*{0}*" -f $ExpectedPublisher)){throw ("Publisher '{0}' does not match expected '{1}'." -f $publisher,$ExpectedPublisher)}
        return $true
    } catch {Write-WorkerLog ("[Direct] AppX/MSIX manifest validation failed: {0}" -f $_.Exception.Message) 'ERROR';return $false}
    finally {if($reader){try{$reader.Dispose()}catch{}};if($archive){try{$archive.Dispose()}catch{}}}
}

function Install-ViaDirectDownload {
    param(
        [string]$AppName,
        [string]$Url,
        [string]$InstallerArgs,
        [string]$ExpectedPublisher,
        [string]$ExpectedSha256 = '',
        [string]$ExpectedInstallerType = '',
        [string]$InteractiveInstallerArgs = '',
        [string[]]$AllowedHosts = @(),
        [ValidateRange(30,7200)][int]$InstallerTimeoutSeconds = 1800,
        [bool]$Interactive = $false,
        [int]$AppBasePercent = 0,
        [int]$AppStepWeight = 33
    )

    if ([string]::IsNullOrWhiteSpace($Url)) {
        Write-WorkerLog "[Direct] No direct URL configured for $AppName; tier skipped." "WARNING" -Percent $AppBasePercent
        return [pscustomobject]@{ Success = $false; ExitCode = -1; Reboot = $false }
    }

    $downloadPath = $null
    $client = $null
    try {
        $uri = [uri]$Url
        if ($uri.Scheme -ne 'https') { throw 'HTTPS is required for direct downloads.' }
        if (@($AllowedHosts).Count -gt 0 -and $uri.Host -notin @($AllowedHosts)) {
            throw ("Download host '{0}' is not in this application's approved host list." -f $uri.Host)
        }

        [Net.ServicePointManager]::SecurityProtocol =
            [Net.ServicePointManager]::SecurityProtocol -bor [Net.SecurityProtocolType]::Tls12

        $downloadPath = Join-Path $DownloadDir ("{0}_{1}.bin" -f
            ($AppName -replace "[^\w-]", "_"), [guid]::NewGuid().ToString("N"))

        Write-WorkerLog "[Direct] Downloading $AppName..." "INFO" -Percent ($AppBasePercent + 5)
        
        $client = New-Object System.Net.WebClient
        $client.Headers.Add("User-Agent", "Mozilla/5.0 (Windows NT 10.0; Win64; x64)")
        
        $script:LastReportedPct = -1
        $progressHandler = {
            param($sender, $e)
            $downloadPct = $e.ProgressPercentage
            if ($downloadPct -ne $script:LastReportedPct -and ($downloadPct % 5 -eq 0)) {
                $script:LastReportedPct = $downloadPct
                $calculatedGlobalPct = $AppBasePercent + [math]::Round(($downloadPct / 100) * ($AppStepWeight * 0.6))
                $bytesMB = [math]::Round($e.BytesReceived / 1MB, 1)
                $totalMB = [math]::Round($e.TotalBytesToReceive / 1MB, 1)
                Write-WorkerLog "[Direct] $AppName Downloading ($downloadPct% - $bytesMB MB / $totalMB MB)..." "INFO" -Percent $calculatedGlobalPct
            }
        }
        $client.add_DownloadProgressChanged($progressHandler)
        
        $downloadCompleted = $false
        $downloadLastError = $null
        for ($downloadAttempt = 1; $downloadAttempt -le 3; $downloadAttempt++) {
            if ($downloadAttempt -gt 1) {
                Write-WorkerLog "[Direct] Retry $downloadAttempt/3 for $AppName after a transient download failure." 'WARNING' -Percent ($AppBasePercent + 5)
                if (Test-Path -LiteralPath $downloadPath) { Remove-Item -LiteralPath $downloadPath -Force -ErrorAction SilentlyContinue }
                if ($client) { try { $client.Dispose() } catch {} }
                $client = New-Object System.Net.WebClient
                $client.Headers.Add('User-Agent', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64)')
                $client.add_DownloadProgressChanged($progressHandler)
            }
            $downloadTask = $client.DownloadFileTaskAsync($Url, $downloadPath)
            $downloadWaitCompleted = $false
            try { $downloadWaitCompleted = $downloadTask.Wait([TimeSpan]::FromMinutes(10)) } catch { $downloadWaitCompleted = $true }
            if (-not $downloadWaitCompleted) {
                try { $client.CancelAsync() } catch {}
                try { [void]$downloadTask.Wait(5000) } catch {}
                $downloadLastError = 'Download timed out after 10 minutes.'
                Write-WorkerLog "[Direct] Attempt $downloadAttempt timed out for $AppName." 'WARNING' -Percent $AppBasePercent
            } elseif ($downloadTask.IsFaulted) {
                $downloadLastError = $downloadTask.Exception.GetBaseException().Message
                Write-WorkerLog "[Direct] Attempt $downloadAttempt failed: $downloadLastError" 'WARNING' -Percent $AppBasePercent
            } elseif ($downloadTask.IsCanceled) {
                $downloadLastError = 'Download was cancelled.'
                Write-WorkerLog "[Direct] Attempt $downloadAttempt was cancelled." 'WARNING' -Percent $AppBasePercent
            } elseif ((Test-Path -LiteralPath $downloadPath) -and (Get-Item -LiteralPath $downloadPath).Length -ge 10240) {
                $downloadCompleted = $true
                break
            } else {
                $downloadLastError = 'Downloaded payload is empty or too small.'
            }
            if ($downloadAttempt -lt 3) { Start-Sleep -Seconds ([int](2 * $downloadAttempt)) }
        }
        if (-not $downloadCompleted) { throw ("Download failed after 3 attempts: {0}" -f $downloadLastError) }

        $stream = [IO.File]::OpenRead($downloadPath)
        try {
            $header = New-Object byte[] 8
            $read = $stream.Read($header, 0, 8)
        } finally {
            $stream.Dispose()
        }

        $kind = $null
        if ($read -ge 2 -and $header[0] -eq 0x4D -and $header[1] -eq 0x5A) {
            $kind = "exe"
        } elseif ($read -ge 4 -and $header[0] -eq 0xD0 -and $header[1] -eq 0xCF -and
                  $header[2] -eq 0x11 -and $header[3] -eq 0xE0) {
            $kind = "msi"
        } elseif ($read -ge 8 -and $header[0] -eq 0xD0 -and $header[1] -eq 0xCF) {
            $kind = 'msi'
        } elseif ($read -ge 4 -and $header[0] -eq 0x50 -and $header[1] -eq 0x4B -and
                  $ExpectedInstallerType -in @('appx','msix')) {
            # AppX/MSIX are ZIP-based signed packages. Windows deployment validates
            # package signature and publisher when Add-AppxPackage stages the package.
            $kind = $ExpectedInstallerType.ToLowerInvariant()
        } elseif ($ExpectedInstallerType -in @('appx','msix') -and $uri.AbsolutePath -match '(?i)\.(appx|msix)$') {
            $kind = $Matches[1].ToLowerInvariant()
        }

        if (-not $kind) { throw 'Downloaded file is not recognized as a supported EXE, MSI, APPX or MSIX installer.' }

        $finalPath = [IO.Path]::ChangeExtension($downloadPath, ".$kind")
        Move-Item -LiteralPath $downloadPath -Destination $finalPath -Force
        $downloadPath = $finalPath

        if ($ExpectedInstallerType -and $ExpectedInstallerType.ToLowerInvariant() -notin @('exe','msi','appx','msix')) {
            throw "Catalog InstallerType must be 'exe', 'msi', 'appx' or 'msix'; received '$ExpectedInstallerType'."
        }
        if ($ExpectedInstallerType -and $kind -ne $ExpectedInstallerType.ToLowerInvariant()) {
            throw ("Installer type mismatch: catalog expects {0}, downloaded payload is {1}." -f $ExpectedInstallerType,$kind)
        }
        if ($ExpectedSha256) {
            if ($ExpectedSha256 -notmatch '^[A-Fa-f0-9]{64}$') { throw 'Catalog SHA-256 value is malformed.' }
            $actualHash = (Get-FileHash -LiteralPath $downloadPath -Algorithm SHA256 -ErrorAction Stop).Hash
            if ($actualHash -ine $ExpectedSha256) { throw ("SHA-256 mismatch. Expected {0}; received {1}." -f $ExpectedSha256,$actualHash) }
            Write-WorkerLog "[Direct] SHA-256 integrity check passed for $AppName." 'SUCCESS' -Percent ($AppBasePercent + 15)
        }
        if ($kind -in @('exe','msi')) {
            if (-not (Test-InstallerSignature -Path $downloadPath -ExpectedPublisher $ExpectedPublisher)) {
                throw 'Installer signature or publisher verification failed.'
            }
        } else {
            if (-not (Test-WorkerAppxPublisher -PackagePath $downloadPath -ExpectedPublisher $ExpectedPublisher)) { throw 'AppX/MSIX manifest publisher validation failed.' }
            Write-WorkerLog "[Direct] Manifest publisher matched; Windows AppX Deployment will enforce package signature and trust policy." 'INFO' -Percent ($AppBasePercent + 15)
        }

        Write-WorkerLog "[Direct] Executing installer for $AppName..." "INFO" -Percent ($AppBasePercent + [math]::Round($AppStepWeight * 0.8))

        # Interactive Install must not inherit silent switches from the catalog's default install recipe.
        $effectiveInstallerArgs = [string]$InstallerArgs
        if ($Interactive -and -not [string]::IsNullOrWhiteSpace($InteractiveInstallerArgs)) {
            $effectiveInstallerArgs = [string]$InteractiveInstallerArgs
        } elseif ($Interactive -and $effectiveInstallerArgs) {
            $effectiveInstallerArgs = $effectiveInstallerArgs -replace '(?i)(^|\s)(--silent|/silent|/S|/quiet|--quiet|/verysilent|/qn)(?=\s|$)', ' '
            $effectiveInstallerArgs = ($effectiveInstallerArgs -replace '\s{2,}', ' ').Trim()
        }

        if ($kind -in @('appx','msix')) {
            if ($Interactive) { Write-WorkerLog "[Direct] $kind uses native Windows package deployment; no separate wizard is provided by the package format." 'INFO' }
            $escapedPackagePath = $downloadPath.Replace("'", "''")
            $deploymentCommand = "try { Add-AppxPackage -Path '$escapedPackagePath' -ErrorAction Stop; exit 0 } catch { [Console]::Error.WriteLine(`$_.Exception.Message); exit 1 }"
            $encodedDeployment = [Convert]::ToBase64String([Text.Encoding]::Unicode.GetBytes($deploymentCommand))
            $powerShellExe = Join-Path $env:WINDIR 'System32\WindowsPowerShell\v1.0\powershell.exe'
            $proc = Invoke-WorkerCapture -FilePath $powerShellExe -ArgumentList @('-NoProfile','-NonInteractive','-ExecutionPolicy','Bypass','-EncodedCommand',$encodedDeployment) -TimeoutSeconds $InstallerTimeoutSeconds
            if ($proc.TimedOut) { Write-WorkerLog "[Direct] $kind deployment timed out for $AppName." 'ERROR' }
            elseif ($proc.ExitCode -ne 0) { Write-WorkerLog ("[Direct] $kind deployment failed: {0}" -f $proc.Error) 'ERROR' }
        } elseif ($kind -eq "msi") {
            $msiArgs = @("/i", "`"$downloadPath`"")
            if (-not $Interactive) { $msiArgs += @("/qn", "/norestart") }
            if ($effectiveInstallerArgs) { $msiArgs += ($effectiveInstallerArgs -split "\s+" | Where-Object { $_ }) }
            $proc = Invoke-ProcessResult -FilePath "msiexec.exe" -ArgumentList $msiArgs -ShowWindow:$Interactive -TimeoutSeconds $InstallerTimeoutSeconds
        } else {
            # Keep the EXE argument string intact so quoted paths (e.g. AnyDesk --install "C:\Program Files...") survive.
            $exeArgs = @()
            if ($effectiveInstallerArgs) { $exeArgs = @($effectiveInstallerArgs) }
            $proc = Invoke-ProcessResult -FilePath $downloadPath -ArgumentList $exeArgs -ShowWindow:$Interactive -TimeoutSeconds $InstallerTimeoutSeconds
        }

        $ok = Test-ExitSuccess -ExitCode $proc.ExitCode
        $reboot = ($proc.ExitCode -in @(1641, 3010))
        if ($ok) {
            Write-WorkerLog "[Direct] Installer finished for $AppName (exit $($proc.ExitCode))." "SUCCESS" -Percent ($AppBasePercent + $AppStepWeight)
        } else {
            Write-WorkerLog "[Direct] Installer failed for $AppName (exit $($proc.ExitCode))." "ERROR" -Percent $AppBasePercent
        }
        return [pscustomobject]@{ Success = $ok; ExitCode = $proc.ExitCode; Reboot = $reboot }
    }
    catch {
        Write-WorkerLog "[Direct] $AppName failed: $_" "ERROR" -Percent $AppBasePercent
        return [pscustomobject]@{ Success = $false; ExitCode = -1; Reboot = $false }
    }
    finally {
        if ($client) { try { $client.Dispose() } catch {} }
        if ($downloadPath -and (Test-Path -LiteralPath $downloadPath)) {
            Remove-Item -LiteralPath $downloadPath -Force -ErrorAction SilentlyContinue
        }
    }
}

$successCount = 0
$unverifiedCount = 0
$cancelledCount = 0
$failedCount  = 0
$skippedCount = 0
$rebootNeeded = $false
$results = New-Object System.Collections.Generic.List[object]

$totalApps = $Apps.Count
$appIndex = 0

$wingetNotFoundOrFetchErrors = @(
    -1,           # Winget unavailable or process did not start
    0x80190194,   # HTTP 404 unsigned HRESULT
    -2145844844,  # HTTP 404 signed Int32 HRESULT
    -1978335212,  # 0x8A150014 - NO_APPLICATIONS_FOUND
    -1978335209,  # 0x8A150017 - NO_MANIFEST_FOUND
    -1978335214   # 0x8A150012 - SOURCE_NAME_DOES_NOT_EXIST
)

foreach ($app in $Apps) {
    $name = [string]$app.Name
    try {
    $appStartedAt = Get-Date
    $appIndex++
    $appBasePercent = [math]::Round((($appIndex - 1) / $totalApps) * 100)
    $appStepWeight  = [math]::Round((1 / $totalApps) * 100)
    
    $configuredId = [string]$app.Id
    $chocoId = [string]$app.ChocoId
    $wasInstalled = Test-WorkerInstalled -AppName $name -AppId $configuredId -ChocoId $chocoId
    $id = if ($ActionCommand -in @('upgrade','repair')) { Resolve-WorkerWingetId -AppName $name -ConfiguredId $configuredId } else { $configuredId }

    if ($ActionCommand -in @('upgrade','repair') -and -not $wasInstalled) {
        Write-WorkerLog "[$name] not detected as installed; $ActionCommand skipped." "INFO" -Percent ($appBasePercent + $appStepWeight)
        $skippedCount++
        [void]$results.Add([pscustomobject]@{ Name=$name; Status="NotInstalled"; ExitCode=0 })
        continue
    }

    if ($ActionCommand -eq "install" -and $wasInstalled) {
        Write-WorkerLog "[$name] already detected in system registry; skipped." "SUCCESS" -Percent ($appBasePercent + $appStepWeight)
        $skippedCount++
        [void]$results.Add([pscustomobject]@{ Name=$name; Status="Skipped"; ExitCode=0 })
        continue
    }

    Write-WorkerLog ("APP-BEGIN | Name={0} | Action={1} | WingetId={2} | ChocolateyId={3} | Interactive={4}" -f $name,$ActionCommand,$configuredId,$chocoId,$Interactive) 'INFO' -Percent $appBasePercent
    Write-WorkerLog "Processing $name ($appIndex of $totalApps)..." "INFO" -Percent $appBasePercent
    $done = $false
    $packageManagerSucceeded = $false
    $appReboot = $false
    $lastExitCode = -1
    $chocoResult = $null

    # Tier 1: native MSI repair when the installed product exposes a Windows Installer product code.
    # Other installers use Winget's force-reinstall path as a best-effort repair fallback.
    if ($ActionCommand -eq 'repair') {
        $wingetResult = Invoke-WorkerMsiRepair -AppName $name -Interactive:$Interactive -BasePercent $appBasePercent -TimeoutSeconds ([int]$app.InstallTimeoutSeconds)
        if ($null -eq $wingetResult) {
            Write-WorkerLog "[$name] No native MSI repair entry found; attempting Winget force-reinstall as best-effort repair." "INFO" -Percent $appBasePercent
            $wingetResult = Install-ViaWinget -TargetId $id -ActionCommand $ActionCommand -ExtraFlags "" -Interactive:$Interactive -BasePercent $appBasePercent -TimeoutSeconds ([int]$app.InstallTimeoutSeconds)
        }
    } else {
        $wingetResult = Install-ViaWinget -TargetId $id -ActionCommand $ActionCommand -ExtraFlags "" -Interactive:$Interactive -BasePercent $appBasePercent -TimeoutSeconds ([int]$app.InstallTimeoutSeconds)
    }
    $lastExitCode = $wingetResult.ExitCode
    if ($wingetResult.Reboot) { $appReboot = $true }

    # Winget uses a non-zero HRESULT when an upgrade is not applicable.
    # This normally means there is no newer applicable version, not that installation failed.
    if ($ActionCommand -eq "upgrade" -and $wingetResult.ExitCode -eq -1978335189) {
        Write-WorkerLog "[$name] Already up to date (Winget: no applicable update found); no action required." "SUCCESS" -Percent ($appBasePercent + $appStepWeight)
        $skippedCount++
        [void]$results.Add([pscustomobject]@{ Name=$name; Status="UpToDate"; ExitCode=$wingetResult.ExitCode })
        continue
    }

    if ($ActionCommand -eq "install" -and $wingetResult.ExitCode -eq -1978335189) {
        # Winget can return UPDATE_NOT_APPLICABLE when the package is already present.
        # Never count this as skipped unless registry/AppX/Winget inventory confirms it.
        $confirmedInstalled = Test-WorkerInstalled -AppName $name -AppId $id -ChocoId $chocoId -SkipWinget
        if ($confirmedInstalled) {
            Write-WorkerLog "[$name] Winget reported no applicable install action and local inventory confirms it is already installed; skipped." "SUCCESS" -Percent ($appBasePercent + $appStepWeight)
            $skippedCount++
            [void]$results.Add([pscustomobject]@{ Name=$name; Status="Skipped"; ExitCode=$wingetResult.ExitCode })
            continue
        }
        Write-WorkerLog "[$name] Winget returned UPDATE_NOT_APPLICABLE, but local installed-state verification did not confirm the app; marking this attempt failed without launching a conflicting fallback." "WARNING" -Percent $appBasePercent
    }

    if ($wingetResult.Success) {
        $done = $true
        if ($ActionCommand -eq 'install') {
            $verified = Wait-WorkerInstalled -AppName $name -AppId $id -ChocoId $chocoId -TimeoutSeconds 45
            if (-not $verified) {
                $done = $false; $packageManagerSucceeded = $true
                Write-WorkerLog "[$name] Winget exited successfully, but installed-state verification timed out. Marked SuccessUnverified; no fallback installer will run." 'WARNING' -Percent $appBasePercent
            }
        }
    } else {
        if ($wingetResult.Started -and ($wingetResult.ExitCode -notin $wingetNotFoundOrFetchErrors)) {
            # Do not launch a second installer after a real installer process failed or was cancelled.
            Write-WorkerLog "[$name] Winget installer started but failed (exit $($wingetResult.ExitCode)); fallback blocked to avoid concurrent or conflicting installation." "WARNING" -Percent $appBasePercent
        } else {
            Write-WorkerLog "[$name] Winget package/source unavailable; moving to Tier 2 (Chocolatey)." "INFO" -Percent $appBasePercent
        }
    }

    # Tier 2: Chocolatey fallback. In Interactive mode it is deliberately skipped because
    # Chocolatey package scripts commonly enforce silent installer switches regardless of console visibility.
    # A package manager that returned success owns the install attempt even when
    # registry/AppX visibility is delayed; never launch a second installer in that case.
    $allowFallback = (-not $wingetResult.Success) -and [bool]$wingetResult.FallbackSafe
    if (-not $done -and $allowFallback -and $ActionCommand -ne "repair" -and -not $Interactive -and -not [string]::IsNullOrWhiteSpace($chocoId)) {
        $chocoAction = if ($ActionCommand -eq "install") { "install" } else { "upgrade" }
        $chocoResult = Install-ViaChocolatey -ChocoId $chocoId -Action $chocoAction -Interactive:$Interactive -BasePercent $appBasePercent -TimeoutSeconds ([int]$app.InstallTimeoutSeconds)
        $lastExitCode = $chocoResult.ExitCode
        if ($chocoResult.Reboot) { $appReboot = $true }

        if ($chocoResult.Success) {
            $done = $true
            if ($ActionCommand -eq 'install') {
                $verified = Wait-WorkerInstalled -AppName $name -AppId $id -ChocoId $chocoId -TimeoutSeconds 45
                if (-not $verified) { $done = $false; $packageManagerSucceeded = $true; Write-WorkerLog "[$name] Chocolatey exit code was successful, but installed-state verification timed out. Marked SuccessUnverified; no second installer will run." 'WARNING' -Percent $appBasePercent }
            }
        } else {
            Write-WorkerLog "[$name] Chocolatey failed (exit $($chocoResult.ExitCode)); direct fallback requires a classified package-source miss." 'WARNING' -Percent $appBasePercent
        }
    }

    if (-not $done -and $allowFallback -and $Interactive -and $ActionCommand -ne "repair") {
        Write-WorkerLog "[$name] Chocolatey fallback skipped in Interactive mode to avoid package scripts forcing silent installation." "INFO" -Percent $appBasePercent
    }

    # Tier 3: Direct Download. Direct installers are permitted only for fresh installs. An EXE/MSI URL does not
    # guarantee a safe in-place upgrade and must never be used as an implicit upgrade path.
    $allowDirectFallback = (-not $packageManagerSucceeded) -and $allowFallback -and ($null -eq $chocoResult -or [bool]$chocoResult.FallbackSafe)
    if (-not $done -and $allowDirectFallback -and $ActionCommand -eq "install") {

        $directResult = Install-ViaDirectDownload -AppName $name -Url ([string]$app.DirectUrl) `
            -InstallerArgs ([string]$app.DirectArgs) -ExpectedPublisher ([string]$app.Publisher) `
            -ExpectedSha256 ([string]$app.Sha256) -ExpectedInstallerType ([string]$app.InstallerType) `
            -InteractiveInstallerArgs ([string]$app.InteractiveArgs) -AllowedHosts @($app.AllowedHosts) `
            -InstallerTimeoutSeconds ([int]$app.InstallTimeoutSeconds) `
            -Interactive:$Interactive -AppBasePercent $appBasePercent -AppStepWeight $appStepWeight
        $lastExitCode = $directResult.ExitCode
        if ($directResult.Reboot) { $appReboot = $true }

        if ($directResult.Success) {
            if (Wait-WorkerInstalled -AppName $name -AppId $id -ChocoId $chocoId -TimeoutSeconds 45) {
                $done = $true
            } else {
                $packageManagerSucceeded = $true
                Write-WorkerLog "[$name] Direct installer exited successfully, but installed-state verification timed out. Marked SuccessUnverified." 'WARNING' -Percent $appBasePercent
            }
        }
    }

    if ($appReboot) { $rebootNeeded = $true }

    if ($lastExitCode -in @(1602,1223)) {
        $cancelledCount++
        Write-WorkerLog "[$name] installation cancelled by user (exit $lastExitCode); no fallback will run." 'WARNING' -Percent ($appBasePercent + $appStepWeight)
        [void]$results.Add([pscustomobject]@{ Name=$name; Status='Cancelled'; ExitCode=$lastExitCode })
    } elseif ($done) {
        $successCount++
        $successStatus = if ($appReboot) { 'NeedsReboot' } else { 'SuccessVerified' }
        Write-WorkerLog "[$name] completed and installed-state verification passed." 'SUCCESS' -Percent ($appBasePercent + $appStepWeight)
        [void]$results.Add([pscustomobject]@{ Name=$name; Status=$successStatus; ExitCode=$lastExitCode })
    } elseif ($packageManagerSucceeded) {
        $unverifiedCount++
        Write-WorkerLog "[$name] installer/package manager reported success, but verification evidence is unavailable. Review diagnostics; no duplicate install was attempted." 'WARNING' -Percent ($appBasePercent + $appStepWeight)
        [void]$results.Add([pscustomobject]@{ Name=$name; Status='SuccessUnverified'; ExitCode=$lastExitCode })
    } else {
        $failedCount++
        Write-WorkerLog "[$name] failed in all applicable tiers; continuing queue." 'ERROR' -Percent ($appBasePercent + $appStepWeight)
        [void]$results.Add([pscustomobject]@{ Name=$name; Status='Failed'; ExitCode=$lastExitCode })
    }
    $appElapsed = [math]::Round(((Get-Date) - $appStartedAt).TotalSeconds,1)
    Write-WorkerLog ("APP-END | Name={0} | ElapsedSeconds={1} | ExitCode={2} | Verified={3}" -f $name,$appElapsed,$lastExitCode,$done) 'INFO'
    } catch {
        $failedCount++
        $appError = $_.Exception.Message
        Write-WorkerLog ("APP-EXCEPTION | Name={0} | Error={1} | Queue will continue." -f $name,$appError) 'ERROR'
        [void]$results.Add([pscustomobject]@{ Name=$name; Status='FailedException'; ExitCode=-1; Error=$appError })
        continue
    }
}

$workerSummary = [pscustomobject]@{
    ActionName   = $ActionName
    SuccessCount = $successCount
    UnverifiedCount = $unverifiedCount
    CancelledCount = $cancelledCount
    FailedCount  = $failedCount
    SkippedCount = $skippedCount
    RebootNeeded = $rebootNeeded
    Results      = $results.ToArray()
}
# Publish completion through an atomic file handoff. This avoids PowerShell 5.1
# generic-collection marshaling and shared-object visibility edge cases between runspaces.
try {
    $workerSummaryJson = ConvertTo-Json -InputObject $workerSummary -Depth 8 -Compress
    if ([string]::IsNullOrWhiteSpace($workerSummaryJson)) { throw 'Worker summary serialization returned an empty payload.' }
    if ([string]::IsNullOrWhiteSpace($CompletionFilePath)) { throw 'Completion file path was not supplied to the worker.' }
    $completionTempPath = $CompletionFilePath + '.tmp.' + [guid]::NewGuid().ToString('N')
    $utf8NoBom = New-Object System.Text.UTF8Encoding($false)
    [System.IO.File]::WriteAllText($completionTempPath, [string]$workerSummaryJson, $utf8NoBom)
    if ([System.IO.File]::Exists($CompletionFilePath)) { [System.IO.File]::Delete($CompletionFilePath) }
    [System.IO.File]::Move($completionTempPath, $CompletionFilePath)
    Write-WorkerLog ("WORKER-PUBLISH | Summary payload committed ({0} characters)." -f $workerSummaryJson.Length) 'INFO'
} catch {
    Write-WorkerLog ("WORKER-PUBLISH-ERROR | {0}" -f $_.Exception.Message) 'ERROR'
    throw
}
Write-WorkerLog "Queue completed." "SUCCESS" -Percent 100
'@

function Set-AMRInstallButtonsEnabled {
    param([bool]$Enabled)

    foreach ($name in @('InstallSelectedBtn','InstallInteractiveBtn','UpdateSelectedBtn','RepairSelectedBtn','UninstallSelectedBtn','DeselectAllBtn')) {
        $button = C $name
        if ($button) { $button.IsEnabled = $Enabled }
    }
}

function Update-AMRInstallProgressFromLogLine {
    param([string]$Line)

    if ([string]::IsNullOrWhiteSpace($Line)) { return $Line }
    $displayLine = $Line
    if ($Line -match '^PROG:(\d+)\|(.*)$') {
        $percent = [math]::Max(0, [math]::Min(100, [int]$matches[1]))
        $displayLine = [string]$matches[2]
        $script:ProgressBar.IsIndeterminate = $false
        $script:ProgressBar.Value = $percent
        return ("{0}%  |  {1}" -f $percent, $displayLine)
    }

    # Package managers and native installers do not consistently expose a numeric
    # percentage. Animate the bar during those waits instead of leaving it frozen
    # at an old milestone or inventing a percentage.
    if ($Line -match '(?i)\[(Winget|Chocolatey|Direct)\].*(Executing|Downloading|Installer started|Running native Windows Installer)') {
        $script:ProgressBar.IsIndeterminate = $true
        return ('Working  |  ' + $Line)
    } elseif ($Line -match '(?i)(Completed|finished|failed|returned code|timed out|APP-END|APP-EXCEPTION|Queue completed)') {
        $script:ProgressBar.IsIndeterminate = $false
    }
    return $displayLine
}

function Complete-AMRInstallQueue {
    param($Result, [string]$ErrorText = '')

    if ($script:InstallTimer) {
        $script:InstallTimer.Stop()
        $script:InstallTimer = $null
    }

    $line = $null
    while ($script:InstallLogQueue.TryDequeue([ref]$line)) {
        if ($line) {
            $line = Update-AMRInstallProgressFromLogLine -Line $line
            try { Add-Content -LiteralPath $script:LogFile -Value $line -Encoding UTF8 -ErrorAction Stop } catch { Write-AMRDiagnostic -Severity 'ERROR' -Area 'Software' -Operation 'AppendInstallQueueLog' -Message 'Could not persist an installer worker log line.' -ErrorRecord $_ -Target $script:LogFile }
            foreach ($key in @('All','Software')) {
                $control = $script:LogControls[$key]
                if ($control) {
                    $control.AppendText("$line`r`n")
                    $control.ScrollToEnd()
                }
            }
            $script:Status.Text = $line
            $script:ProgressText.Text = $line
        }
        $line = $null
    }

    if ($script:InstallPowerShell) {
        try { $script:InstallPowerShell.Dispose() } catch {}
        $script:InstallPowerShell = $null
    }
    if ($script:InstallRunspace) {
        try { $script:InstallRunspace.Close(); $script:InstallRunspace.Dispose() } catch {}
        $script:InstallRunspace = $null
    }

    $script:InstallAsyncResult = $null
    $script:InstallOutput = $null
    $script:InstallResultQueue = $null
    if ($script:InstallCompletionFile) { try { Remove-Item -LiteralPath $script:InstallCompletionFile -Force -ErrorAction SilentlyContinue } catch {}; $script:InstallCompletionFile = $null }
    $script:InstallRunning = $false

    foreach ($app in $script:SoftwareCatalog) { $app.IsSelected = $false }
    $script:AppsView.Refresh()
    Set-AMRInstallButtonsEnabled -Enabled $true

    if ($ErrorText) {
        $script:ProgressBar.IsIndeterminate = $false
        $script:ProgressBar.Value = 0
        $script:ProgressText.Text = "Installation failed with error."
        Write-AMRLog "Installation worker failed: $ErrorText" ERROR Software
        Show-AMRMessage "The installation worker stopped unexpectedly:`n`n$ErrorText" "Engine Error" OK Error | Out-Null
        return
    }

    if (-not $Result) {
        Show-AMRMessage "The operation finished without returning a result." "Engine Warning" OK Warning | Out-Null
        return
    }

    $summary = "$($Result.ActionName) Summary:`n`n" +
               "✔ Verified successes: $($Result.SuccessCount)`n" +
               "⚠ Success, verification pending: $($Result.UnverifiedCount)`n" +
               "↩ Cancelled: $($Result.CancelledCount)`n" +
               "⏭ Skipped (already installed): $($Result.SkippedCount)`n" +
               "❌ Failed: $($Result.FailedCount)"

    if ($Result.RebootNeeded) {
        $summary += "`n`n⚠ One or more installers requested a restart (1641/3010)."
    }

    $script:ProgressBar.IsIndeterminate = $false
    $script:ProgressBar.Value = 100
    $script:ProgressText.Text = "Finished: $($Result.SuccessCount) Verified, $($Result.UnverifiedCount) Unverified, $($Result.CancelledCount) Cancelled, $($Result.SkippedCount) Skipped, $($Result.FailedCount) Failed."
    Write-AMRLog "Queue finished. Verified: $($Result.SuccessCount), Unverified: $($Result.UnverifiedCount), Cancelled: $($Result.CancelledCount), Skipped: $($Result.SkippedCount), Failed: $($Result.FailedCount)." SUCCESS Software
    Show-AMRMessage $summary "Operation Summary" OK Information | Out-Null
}

function Execute-SmartMultiTierInstallAsync {
    param(
        [string]$ActionCommand,
        [string]$ActionName,
        [string]$ExtraFlags = '',
        [switch]$Interactive
    )

    if ($script:InstallRunning) {
        Write-AMRLog "An installation queue is already running." WARNING Software
        return
    }

    if ($ActionCommand -notin @('install','upgrade','repair')) {
        Show-AMRMessage "Unsupported software action: $ActionCommand" "Invalid Action" OK Error | Out-Null
        return
    }

    $selectedSnapshot = @(
        $script:SoftwareCatalog |
        Where-Object { $_.IsSelected -eq $true } |
        ForEach-Object {
            [pscustomobject]@{
                Name       = [string]$_.Name
                Category   = [string]$_.Category
                Id         = [string]$_.Id
                ChocoId    = [string]$_.ChocoId
                DirectUrl  = [string]$_.DirectUrl
                DirectArgs = [string]$_.DirectArgs
                Publisher  = [string]$_.Publisher
                Sha256     = [string]$_.Sha256
                InstallerType = [string]$_.InstallerType
                InteractiveArgs = [string]$_.InteractiveArgs
                AllowedHosts = @($_.AllowedHosts)
                InstallTimeoutSeconds = if ($_.InstallTimeoutSeconds) { [int]$_.InstallTimeoutSeconds } else { 1800 }
            }
        }
    )

    if ($selectedSnapshot.Count -eq 0) {
        Show-AMRMessage "Please select at least one application." "Selection Required" OK Warning | Out-Null
        return
    }

    $script:InstallRunning = $true
    $script:InstallActionName = $ActionName
    $script:InstallSelectedSnapshot = $selectedSnapshot
    $script:ProgressBar.IsIndeterminate = $false
    $script:ProgressBar.Value = 0
    $script:ProgressText.Text = "Initializing $ActionName..."
    Set-AMRInstallButtonsEnabled -Enabled $false

    Write-AMRLog "Starting $ActionName for $($selectedSnapshot.Count) application(s)." INFO Software

    try {
        $discardedLine = $null
        while ($script:InstallLogQueue.TryDequeue([ref]$discardedLine)) {
            $discardedLine = $null
        }

        $script:InstallRunspace = [System.Management.Automation.Runspaces.RunspaceFactory]::CreateRunspace()
        $script:InstallRunspace.ApartmentState = [System.Threading.ApartmentState]::MTA
        $script:InstallRunspace.ThreadOptions = [System.Management.Automation.Runspaces.PSThreadOptions]::ReuseThread
        $script:InstallRunspace.Open()

        $script:InstallCompletionFile = Join-Path ([IO.Path]::GetTempPath()) ('AMR_SW_COMPLETION_' + [guid]::NewGuid().ToString('N') + '.json')
        $script:InstallPowerShell = [PowerShell]::Create()
        $script:InstallPowerShell.Runspace = $script:InstallRunspace

        [void]$script:InstallPowerShell.AddScript($script:InstallWorkerCode)
        [void]$script:InstallPowerShell.AddArgument($selectedSnapshot)
        [void]$script:InstallPowerShell.AddArgument($ActionCommand)
        [void]$script:InstallPowerShell.AddArgument($ActionName)
        [void]$script:InstallPowerShell.AddArgument([bool]$Interactive)
        [void]$script:InstallPowerShell.AddArgument($script:DownloadDir)
        [void]$script:InstallPowerShell.AddArgument($script:InstallLogQueue)
        [void]$script:InstallPowerShell.AddArgument([string]$script:InstallCompletionFile)
        $script:InstallOutput = $null
        # Start asynchronously; the worker commits one summary to its unique completion file.
        $script:InstallAsyncResult = $script:InstallPowerShell.BeginInvoke()

        $script:InstallTimer = New-Object System.Windows.Threading.DispatcherTimer
        $script:InstallTimer.Interval = [TimeSpan]::FromMilliseconds(150)
        $script:InstallTimer.Add_Tick({
            $queuedLine = $null
            while ($script:InstallLogQueue.TryDequeue([ref]$queuedLine)) {
                if ($queuedLine) {
                    $queuedLine = Update-AMRInstallProgressFromLogLine -Line $queuedLine
                    try { Add-Content -LiteralPath $script:LogFile -Value $queuedLine -Encoding UTF8 -ErrorAction Stop } catch { Write-AMRDiagnostic -Severity 'ERROR' -Area 'Software' -Operation 'AppendInstallTimerLog' -Message 'Could not persist an installer progress log line.' -ErrorRecord $_ -Target $script:LogFile }
                    foreach ($key in @('All','Software')) {
                        $control = $script:LogControls[$key]
                        if ($control) {
                            $control.AppendText("$queuedLine`r`n")
                            $control.ScrollToEnd()
                        }
                    }
                    $script:Status.Text = $queuedLine
                    $script:ProgressText.Text = $queuedLine
                }
                $queuedLine = $null
            }

            if ($script:InstallAsyncResult -and $script:InstallAsyncResult.IsCompleted) {
                if ($script:InstallTimer) { $script:InstallTimer.Stop() }
                $resultObject = $null
                $errorMessage = ''
                try {
                    # Read the atomically committed worker summary from its unique file.
                    $summaryPayload = [string]::Empty
                    if ($script:InstallCompletionFile -and [System.IO.File]::Exists($script:InstallCompletionFile)) {
                        $summaryPayload = [System.IO.File]::ReadAllText($script:InstallCompletionFile)
                        if ([string]::IsNullOrWhiteSpace($summaryPayload)) {
                            $errorMessage = 'The installation worker published an empty completion payload.'
                        } else {
                            try {
                                $resultObject = ConvertFrom-Json -InputObject $summaryPayload -ErrorAction Stop
                                # Normal completion summaries do not contain WorkerError fields.
                                # Under StrictMode, reading a missing PSCustomObject property throws;
                                # inspect the property collection before reading optional diagnostics.
                                if ($null -ne $resultObject) {
                                    $workerErrorProperty = $resultObject.PSObject.Properties['WorkerError']
                                    if ($workerErrorProperty -and -not [string]::IsNullOrWhiteSpace([string]$workerErrorProperty.Value)) {
                                        $workerDiagnostic = "Worker fatal error: $([string]$workerErrorProperty.Value)"
                                        $workerErrorTypeProperty = $resultObject.PSObject.Properties['WorkerErrorType']
                                        $workerStackProperty = $resultObject.PSObject.Properties['WorkerStackTrace']
                                        if ($workerErrorTypeProperty -and $workerErrorTypeProperty.Value) { $workerDiagnostic += " | Type=$([string]$workerErrorTypeProperty.Value)" }
                                        if ($workerStackProperty -and $workerStackProperty.Value) { $workerDiagnostic += " | Stack=$([string]$workerStackProperty.Value)" }
                                        $errorMessage = $workerDiagnostic
                                    }
                                }
                            } catch {
                                $errorMessage = 'The installation worker published an unreadable completion payload: ' + $_.Exception.Message
                            }
                        }
                    } else {
                        $workerState = 'Unknown'
                        $workerReason = ''
                        try {
                            if ($script:InstallPowerShell -and $script:InstallPowerShell.InvocationStateInfo) {
                                $workerState = [string]$script:InstallPowerShell.InvocationStateInfo.State
                                if ($script:InstallPowerShell.InvocationStateInfo.Reason) {
                                    $workerReason = [string]$script:InstallPowerShell.InvocationStateInfo.Reason.Exception.Message
                                }
                            }
                        } catch {}
                        $errorMessage = "The installation worker ended without committing its completion file. WorkerState=$workerState. $workerReason Check WORKER-PUBLISH diagnostics and the PowerShell error stream."
                    }
                } catch {
                    $errorMessage = $_.Exception.Message
                }

                if ($script:InstallPowerShell.Streams.Error.Count -gt 0) {
                    $streamErrors = ($script:InstallPowerShell.Streams.Error | ForEach-Object {
                        $detail = $_.ToString()
                        if ($_.InvocationInfo -and $_.InvocationInfo.PositionMessage) { $detail += "`n" + $_.InvocationInfo.PositionMessage }
                        if ($_.ScriptStackTrace) { $detail += "`nStack: " + $_.ScriptStackTrace }
                        $detail
                    }) -join "`n--- Worker Error ---`n"
                    Write-AMRLog ("WORKER-ERROR-STREAM | " + $streamErrors) ERROR Software
                    if (-not $resultObject) { $errorMessage = $streamErrors }
                    else { Write-AMRLog "Worker reported non-terminating errors: $streamErrors" WARNING Software }
                }

                if (-not $resultObject -and -not $errorMessage) {
                    $errorMessage = "The worker completed but did not return a valid summary object."
                }

                Complete-AMRInstallQueue -Result $resultObject -ErrorText $errorMessage
            }
        })
        $script:InstallTimer.Start()
    }
    catch {
        Complete-AMRInstallQueue -Result $null -ErrorText $_.Exception.Message
    }
}

# --- SAFE SOFTWARE UNINSTALL ENGINE ---
function Show-AMRUninstallChoice {
    param([string[]]$ApplicationNames)

    $dialog = New-Object System.Windows.Window
    $dialog.Title = 'AMR | Uninstall Options'
    $dialog.Owner = $script:Window
    $dialog.WindowStartupLocation = 'CenterOwner'
    $dialog.SizeToContent = 'WidthAndHeight'
    $dialog.MinWidth = 500
    $dialog.MaxWidth = 620
    $dialog.ResizeMode = 'NoResize'
    $dialog.Background = [System.Windows.Media.BrushConverter]::new().ConvertFromString('#18181B')
    $dialog.Foreground = [System.Windows.Media.Brushes]::White
    $dialog.ShowInTaskbar = $false

    $root = New-Object System.Windows.Controls.StackPanel
    $root.Margin = '20'
    $heading = New-Object System.Windows.Controls.TextBlock
    $heading.Text = 'Choose how AMR should remove the selected app(s)'
    $heading.FontSize = 17; $heading.FontWeight = 'Bold'; $heading.Foreground = [System.Windows.Media.Brushes]::White
    $root.Children.Add($heading) | Out-Null
    $names = New-Object System.Windows.Controls.TextBlock
    $names.Text = ($ApplicationNames | ForEach-Object { '• ' + $_ }) -join "`n"
    $names.Margin = '0,8,0,12'; $names.Foreground = [System.Windows.Media.BrushConverter]::new().ConvertFromString('#A1A1AA')
    $names.TextWrapping = 'Wrap'; $names.MaxHeight = 90
    $root.Children.Add($names) | Out-Null

    # Use a restrained, static button template so WPF's default theme does not
    # apply the overly bright hover/focus animation to these destructive choices.
    function New-AMRUninstallButtonStyle {
        param([string]$HoverColor, [string]$PressedColor, [string]$BorderColor = '#465365', [string]$HoverBorderColor = '#718096')
        $styleXaml = @"
<Style xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation" TargetType="{x:Type Button}" xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml">
  <Setter Property="BorderThickness" Value="1"/>
  <Setter Property="BorderBrush" Value="$BorderColor"/>
  <Setter Property="FocusVisualStyle" Value="{x:Null}"/>
  <Setter Property="Template">
    <Setter.Value>
      <ControlTemplate TargetType="{x:Type Button}">
        <Border x:Name="ButtonBorder" Background="{TemplateBinding Background}" BorderBrush="{TemplateBinding BorderBrush}" BorderThickness="{TemplateBinding BorderThickness}" CornerRadius="7" SnapsToDevicePixels="True">
          <ContentPresenter HorizontalAlignment="Center" VerticalAlignment="Center" Margin="8,2" RecognizesAccessKey="True"/>
        </Border>
        <ControlTemplate.Triggers>
          <Trigger Property="IsMouseOver" Value="True">
            <Setter TargetName="ButtonBorder" Property="Background" Value="$HoverColor"/>
            <Setter TargetName="ButtonBorder" Property="BorderBrush" Value="$HoverBorderColor"/>
          </Trigger>
          <Trigger Property="IsPressed" Value="True">
            <Setter TargetName="ButtonBorder" Property="Background" Value="$PressedColor"/>
          </Trigger>
          <Trigger Property="IsEnabled" Value="False">
            <Setter TargetName="ButtonBorder" Property="Opacity" Value="0.55"/>
          </Trigger>
        </ControlTemplate.Triggers>
      </ControlTemplate>
    </Setter.Value>
  </Setter>
</Style>
"@
        return [Windows.Markup.XamlReader]::Parse($styleXaml)
    }

    $result = @{ Choice = 'Cancel' }
    $preserve = New-Object System.Windows.Controls.Button
    $preserve.Content = 'Uninstall only — keep data & settings'
    $preserve.Height = 40; $preserve.Margin = '0,0,0,8'; $preserve.Padding = '12,8'
    $preserve.Background = [System.Windows.Media.BrushConverter]::new().ConvertFromString('#293B50')
    $preserve.Foreground = [System.Windows.Media.Brushes]::White; $preserve.FontWeight = 'SemiBold'
    $preserve.Cursor = [System.Windows.Input.Cursors]::Hand
    $preserve.Style = New-AMRUninstallButtonStyle -HoverColor '#354B63' -PressedColor '#1D2B3B'
    $preserve.Add_Click({ $result.Choice = 'UninstallOnly'; $dialog.Close() }.GetNewClosure())
    $root.Children.Add($preserve) | Out-Null

    $complete = New-Object System.Windows.Controls.Button
    $complete.Content = 'Complete uninstall — remove app files & settings too'
    $complete.Height = 40; $complete.Margin = '0,0,0,8'; $complete.Padding = '12,8'
    $complete.Background = [System.Windows.Media.BrushConverter]::new().ConvertFromString('#B94A52')
    $complete.Foreground = [System.Windows.Media.Brushes]::White; $complete.FontWeight = 'SemiBold'
    $complete.Cursor = [System.Windows.Input.Cursors]::Hand
    $complete.Style = New-AMRUninstallButtonStyle -HoverColor '#C65A62' -PressedColor '#963842' -BorderColor '#D9777E' -HoverBorderColor '#E58B91'
    $complete.Add_Click({ $result.Choice = 'Complete'; $dialog.Close() }.GetNewClosure())
    $root.Children.Add($complete) | Out-Null

    $note = New-Object System.Windows.Controls.TextBlock
    $note.Text = 'Complete uninstall targets only verified app-specific folders and registry entries. Personal documents, projects, downloads, and shared folders are protected.'
    $note.TextWrapping = 'Wrap'; $note.Foreground = [System.Windows.Media.BrushConverter]::new().ConvertFromString('#FBBF24'); $note.Margin = '0,4,0,10'
    $root.Children.Add($note) | Out-Null
    $cancel = New-Object System.Windows.Controls.Button
    $cancel.Content = 'Cancel'; $cancel.HorizontalAlignment = 'Right'; $cancel.Width = 110; $cancel.Height = 34
    $cancel.Background = [System.Windows.Media.BrushConverter]::new().ConvertFromString('#B94A52'); $cancel.Foreground = [System.Windows.Media.Brushes]::White
    $cancel.BorderBrush = [System.Windows.Media.BrushConverter]::new().ConvertFromString('#D9777E')
    $cancel.Cursor = [System.Windows.Input.Cursors]::Hand
    $cancel.Style = New-AMRUninstallButtonStyle -HoverColor '#C65A62' -PressedColor '#963842' -BorderColor '#D9777E' -HoverBorderColor '#E58B91'
    $cancel.Add_Click({ $dialog.Close() })
    $root.Children.Add($cancel) | Out-Null
    $dialog.Content = $root
    [void]$dialog.ShowDialog()
    return [string]$result.Choice
}

function Get-AMRExactUninstallEntry {
    param([string]$AppName)
    $paths = @(
        'HKLM:\Software\Microsoft\Windows\CurrentVersion\Uninstall\*',
        'HKLM:\Software\Wow6432Node\Microsoft\Windows\CurrentVersion\Uninstall\*',
        'HKCU:\Software\Microsoft\Windows\CurrentVersion\Uninstall\*',
        'HKCU:\Software\Wow6432Node\Microsoft\Windows\CurrentVersion\Uninstall\*'
    )
    foreach ($path in $paths) {
        try {
            $entry = Get-ItemProperty -Path $path -ErrorAction SilentlyContinue | Where-Object {
                $_.PSObject.Properties['DisplayName'] -and ([string]$_.DisplayName).Trim().Equals($AppName.Trim(), [StringComparison]::OrdinalIgnoreCase)
            } | Select-Object -First 1
            if ($entry) { return $entry }
        } catch {}
    }
    return $null
}

function Get-AMRSafeCleanupCandidates {
    param($App)
    $candidates = New-Object System.Collections.Generic.List[string]
    $entry = Get-AMRExactUninstallEntry -AppName ([string]$App.Name)
    # InstallLocation is optional in Windows uninstall registry entries. Access it
    # through PSObject.Properties so entries without that value cannot throw.
    $installLocationProperty = if ($entry) { $entry.PSObject.Properties['InstallLocation'] } else { $null }
    if ($installLocationProperty -and -not [string]::IsNullOrWhiteSpace([string]$installLocationProperty.Value)) {
        try {
            $full = [IO.Path]::GetFullPath([string]$installLocationProperty.Value).TrimEnd('\')
            $leaf = [IO.Path]::GetFileName($full)
            $normLeaf = ($leaf -replace '[^a-zA-Z0-9]','').ToLowerInvariant()
            $normName = ([string]$App.Name -replace '[^a-zA-Z0-9]','').ToLowerInvariant()
            $protectedRoots = @($env:USERPROFILE, $env:ProgramFiles, ${env:ProgramFiles(x86)}, $env:ProgramData, $env:WINDIR) | Where-Object { $_ }
            $isProtectedRoot = $false
            foreach ($rootPath in $protectedRoots) {
                try { if ($full.Equals([IO.Path]::GetFullPath($rootPath).TrimEnd('\'), [StringComparison]::OrdinalIgnoreCase)) { $isProtectedRoot = $true } } catch {}
            }
            if (-not $isProtectedRoot -and $normLeaf -eq $normName -and (Test-Path -LiteralPath $full -PathType Container)) { $candidates.Add($full) }
        } catch {}
    }
    # AppData is included only when the folder name is an exact normalized match.
    $appDataRoots = @((Join-Path $env:APPDATA ''), (Join-Path $env:LOCALAPPDATA '')) | Where-Object { $_ }
    $normalizedName = ([string]$App.Name -replace '[^a-zA-Z0-9]','').ToLowerInvariant()
    foreach ($rootPath in $appDataRoots) {
        try {
            if (Test-Path -LiteralPath $rootPath) {
                foreach ($folder in @(Get-ChildItem -LiteralPath $rootPath -Directory -ErrorAction SilentlyContinue)) {
                    $normalizedLeaf = ($folder.Name -replace '[^a-zA-Z0-9]','').ToLowerInvariant()
                    if ($normalizedLeaf -eq $normalizedName -and -not $candidates.Contains($folder.FullName)) { $candidates.Add($folder.FullName) }
                }
            }
        } catch {}
    }
    return @($candidates)
}

function Remove-AMRExactUninstallRegistryEntry {
    param([string]$AppName)
    $entry = Get-AMRExactUninstallEntry -AppName $AppName
    if (-not $entry) { return $false }
    $keyPath = [string]$entry.PSPath
    if ([string]::IsNullOrWhiteSpace($keyPath)) { return $false }
    # Re-check the exact DisplayName immediately before deleting this one uninstall metadata key.
    try {
        $current = Get-ItemProperty -LiteralPath $keyPath -ErrorAction Stop
        if (-not $current.PSObject.Properties['DisplayName'] -or
            -not ([string]$current.DisplayName).Trim().Equals($AppName.Trim(), [StringComparison]::OrdinalIgnoreCase)) { return $false }
        Remove-Item -LiteralPath $keyPath -Recurse -Force -ErrorAction Stop
        Write-AMRLog "Removed exact uninstall registry metadata for '$AppName'." SUCCESS Software
        return $true
    } catch {
        Write-AMRLog "Could not remove exact uninstall registry metadata for '$AppName': $($_.Exception.Message)" WARNING Software
        return $false
    }
}

function Wait-AMRUninstallProcess {
    param(
        [Parameter(Mandatory=$true)]$Process,
        [Parameter(Mandatory=$true)][string]$AppName
    )

    if (-not $Process) { throw 'The uninstaller process was not created.' }
    $script:ProgressBar.IsIndeterminate = $true
    $script:ProgressText.Text = "Uninstalling $AppName... waiting for the uninstaller to finish."

    # Keep WPF responsive while a native uninstaller runs. The indeterminate bar
    # intentionally communicates activity, not a fabricated percentage.
    $frame = New-Object System.Windows.Threading.DispatcherFrame
    $timer = New-Object System.Windows.Threading.DispatcherTimer
    $timer.Interval = [TimeSpan]::FromMilliseconds(180)
    $tickHandler = {
        try {
            $Process.Refresh()
            if ($Process.HasExited) {
                $timer.Stop()
                $frame.Continue = $false
            }
        } catch {
            $timer.Stop()
            $frame.Continue = $false
        }
    }.GetNewClosure()
    $timer.Add_Tick($tickHandler)
    try {
        $timer.Start()
        [System.Windows.Threading.Dispatcher]::PushFrame($frame)
        $Process.Refresh()
        if (-not $Process.HasExited) { [void]$Process.WaitForExit() }
        return [int]$Process.ExitCode
    } finally {
        try { $timer.Stop(); $timer.Remove_Tick($tickHandler) } catch {}
        $script:ProgressBar.IsIndeterminate = $false
    }
}

function Invoke-AMRExactNativeUninstall {
    param(
        $App,
        [bool]$KeepData = $true,
        [bool]$Complete = $false
    )

    # Keep a full attempt trail. A failed registry uninstaller must NOT prevent
    # trying the exact package-manager identity configured for this catalog item.
    $attempts = New-Object System.Collections.Generic.List[string]
    $entry = Get-AMRExactUninstallEntry -AppName ([string]$App.Name)

    if ($entry) {
        $isMsi = $false
        try { $isMsi = ([int]$entry.WindowsInstaller -eq 1) } catch {}
        $quietUninstallText = ''
        $normalUninstallText = ''
        if ($entry.PSObject.Properties['QuietUninstallString']) { $quietUninstallText = [string]$entry.QuietUninstallString }
        if ($entry.PSObject.Properties['UninstallString']) { $normalUninstallText = [string]$entry.UninstallString }
        $uninstallText = if (-not [string]::IsNullOrWhiteSpace($quietUninstallText)) {
            $quietUninstallText
        } else { $normalUninstallText }
        $productCode = $null
        if ($uninstallText -match '(?i)\{[0-9a-f]{8}-(?:[0-9a-f]{4}-){3}[0-9a-f]{12}\}') { $productCode = $Matches[0] }
        if (-not $productCode -and [string]$entry.PSChildName -match '^\{[0-9a-fA-F-]{36}\}$') { $productCode = [string]$entry.PSChildName }

        if (($isMsi -or $productCode) -and $productCode) {
            try {
                $msiArgs = @('/x', $productCode)
                if (-not $KeepData) { $msiArgs += @('/qn', '/norestart') }
                else { $msiArgs += @('/passive', '/norestart') }
                $proc = Start-Process -FilePath 'msiexec.exe' -ArgumentList $msiArgs -PassThru -ErrorAction Stop
                $uninstallExitCode = Wait-AMRUninstallProcess -Process $proc -AppName ([string]$App.Name)
                try { $proc.Dispose() } catch {}
                if ($uninstallExitCode -in @(0,1641,3010)) {
                    return [pscustomobject]@{ Success=$true; Detail="Native MSI uninstall succeeded (exit $uninstallExitCode)." }
                }
                $attempts.Add("MSI uninstall returned exit code $uninstallExitCode")
            } catch { $attempts.Add("MSI uninstall error: $($_.Exception.Message)") }
        } elseif (-not [string]::IsNullOrWhiteSpace($uninstallText)) {
            try {
                # Parse quoted executable paths correctly; never use Invoke-Expression.
                if ($uninstallText -match '^\s*"(?<exe>[^"]+)"\s*(?<args>.*)$') {
                    $exe = $Matches.exe; $args = [string]$Matches.args
                } elseif ($uninstallText -match '^\s*(?<exe>.+?\.exe)\s*(?<args>.*)$') {
                    $exe = $Matches.exe.Trim('"'); $args = [string]$Matches.args
                } else {
                    throw "Could not safely parse uninstall command: $uninstallText"
                }
                if (-not (Test-Path -LiteralPath $exe -PathType Leaf)) {
                    throw "Uninstaller executable was not found: $exe"
                }
                # Resolve the product installation directory for uninstallers that
                # require their original working directory (notably NSIS).
                $installDir = ''
                $installLocationProperty = $entry.PSObject.Properties['InstallLocation']
                if ($installLocationProperty) { $installDir = [string]$installLocationProperty.Value }
                if ([string]::IsNullOrWhiteSpace($installDir)) {
                    try {
                        $installDir = Split-Path -Parent $exe
                    } catch { $installDir = '' }
                }
                if ([string]$App.Id -ieq 'MetaBrainz.Picard' -and
                    (Test-Path -LiteralPath 'HKLM:\Software\MusicBrainz\Picard')) {
                    try {
                        $picardInstall = (Get-ItemProperty -LiteralPath 'HKLM:\\Software\\Musicbrainz\\Picard' -Name InstallDir -ErrorAction Stop).InstallDir
                        if (-not [string]::IsNullOrWhiteSpace([string]$picardInstall) -and
                            (Test-Path -LiteralPath ([string]$picardInstall) -PathType Container)) {
                            $installDir = [string]$picardInstall
                        }
                    } catch {}
                }

                # MusicBrainz Picard's Windows installer is NSIS-based. Its own
                # installer source explicitly launches uninst.exe with:
                #   /S _?=<original install directory>
                # Running the registry UninstallString unchanged opens the
                # interactive uninstaller and can leave this utility waiting.
                # Apply the same verified NSIS convention to uninst.exe entries.
                $isNsisUninstaller = ([IO.Path]::GetFileName($exe) -ieq 'uninst.exe')
                if (-not $isNsisUninstaller) {
                    # Some NSIS builds use uninstall.exe. Detect the NSIS marker
                    # before adding NSIS-only switches to avoid guessing.
                    try {
                        $probeLength = [int][Math]::Min((Get-Item -LiteralPath $exe -ErrorAction Stop).Length, 2097152)
                        if ($probeLength -gt 0) {
                            $stream = [IO.File]::OpenRead($exe)
                            try {
                                $buffer = New-Object byte[] $probeLength
                                [void]$stream.Read($buffer, 0, $probeLength)
                                $probeText = [Text.Encoding]::ASCII.GetString($buffer)
                                if ($probeText -match '(?i)Nullsoft Install System') { $isNsisUninstaller = $true }
                            } finally { $stream.Dispose() }
                        }
                    } catch {}
                }

                $uninstallArgsText = [string]$args
                if ($isNsisUninstaller) {
                    if ($uninstallArgsText -notmatch '(?i)(^|\s)/S(\s|$)') {
                        $uninstallArgsText = ($uninstallArgsText + ' /S').Trim()
                    }
                    if (-not [string]::IsNullOrWhiteSpace($installDir) -and $uninstallArgsText -notmatch '(?i)_\?=') {
                        $uninstallArgsText += (' _?="' + $installDir.TrimEnd('\') + '"')
                    }
                    $attempts.Add("Detected NSIS uninstaller; supplied silent mode and original install directory.")
                }

                $proc = Start-Process -FilePath $exe -ArgumentList $uninstallArgsText -PassThru -ErrorAction Stop
                $uninstallExitCode = Wait-AMRUninstallProcess -Process $proc -AppName ([string]$App.Name)
                try { $proc.Dispose() } catch {}
                if ($uninstallExitCode -in @(0,1641,3010)) {
                    return [pscustomobject]@{ Success=$true; Detail="Native uninstaller succeeded (exit $uninstallExitCode)." }
                }
                $attempts.Add("Native uninstaller returned exit code $uninstallExitCode")
            } catch { $attempts.Add("Native uninstaller error: $($_.Exception.Message)") }
        } else {
            $attempts.Add('Exact registry entry exists but has no usable uninstall command.')
        }
    } else {
        $attempts.Add('No exact DisplayName registry uninstall entry was found.')
    }

    # AppX/MSIX: exact package identity only. Do not remove packages by partial name.
    try {
        $appxIds = @([string]$App.Id, [string]$App.Name) | Where-Object { -not [string]::IsNullOrWhiteSpace($_) }
        $appxPackage = Get-AppxPackage -ErrorAction SilentlyContinue | Where-Object {
            $pkg = $_
            foreach ($identity in $appxIds) {
                if ($pkg.Name -ieq $identity -or $pkg.PackageFamilyName -ieq $identity -or $pkg.PackageFullName -ieq $identity) { return $true }
            }
            return $false
        } | Select-Object -First 1
        if ($appxPackage) {
            try {
                if ($KeepData) {
                    $removeCommand = Get-Command Remove-AppxPackage -ErrorAction Stop
                    if (-not $removeCommand.Parameters.ContainsKey('PreserveApplicationData')) {
                        $attempts.Add('AppX package found, but this Windows version cannot preserve its application data.')
                    } else {
                        Remove-AppxPackage -Package ([string]$appxPackage.PackageFullName) -PreserveApplicationData -ErrorAction Stop
                        return [pscustomobject]@{ Success=$true; Detail='Exact AppX/MSIX package removed for current user; app data preservation requested.' }
                    }
                } else {
                    Remove-AppxPackage -Package ([string]$appxPackage.PackageFullName) -ErrorAction Stop
                    return [pscustomobject]@{ Success=$true; Detail='Exact AppX/MSIX package removed for current user.' }
                }
            } catch { $attempts.Add("AppX/MSIX uninstall error: $($_.Exception.Message)") }
        }
    } catch { $attempts.Add("AppX/MSIX detection error: $($_.Exception.Message)") }

    # Scoop: match an exact installed app directory, then invoke Scoop by that exact name.
    try {
        $scoopCandidates = @([string]$App.Name, [string]$App.Id, [string]$App.ChocoId) |
            Where-Object { -not [string]::IsNullOrWhiteSpace($_) } |
            ForEach-Object { ($_ -replace '[^a-zA-Z0-9]','').ToLowerInvariant() } |
            Where-Object { $_.Length -ge 3 } | Select-Object -Unique
        $scoopRoots = @()
        if ($env:SCOOP) { $scoopRoots += $env:SCOOP }
        if ($env:SCOOP_GLOBAL) { $scoopRoots += $env:SCOOP_GLOBAL }
        if ($env:USERPROFILE) { $scoopRoots += (Join-Path $env:USERPROFILE 'scoop') }
        if ($env:ProgramData) { $scoopRoots += (Join-Path $env:ProgramData 'scoop') }
        $scoopAppName = $null
        foreach ($rootPath in @($scoopRoots | Select-Object -Unique)) {
            $appsPath = Join-Path $rootPath 'apps'
            if (-not (Test-Path -LiteralPath $appsPath -PathType Container)) { continue }
            foreach ($folder in @(Get-ChildItem -LiteralPath $appsPath -Directory -ErrorAction SilentlyContinue)) {
                $observed = ($folder.Name -replace '[^a-zA-Z0-9]','').ToLowerInvariant()
                if ($scoopCandidates -contains $observed) { $scoopAppName = [string]$folder.Name; break }
            }
            if ($scoopAppName) { break }
        }
        if ($scoopAppName) {
            $scoop = Get-Command scoop -ErrorAction SilentlyContinue
            if ($scoop) {
                $scoopArgs = @('uninstall', $scoopAppName)
                if ($Complete) { $scoopArgs += '--purge' }
                & $scoop.Source @scoopArgs 2>&1 | Out-Null
                $scoopExitCode = $LASTEXITCODE
                if ($scoopExitCode -eq 0) { return [pscustomobject]@{ Success=$true; Detail="Scoop removed exact app '$scoopAppName' (exit 0)." } }
                $attempts.Add("Scoop uninstall returned exit code $scoopExitCode for '$scoopAppName'.")
            } else { $attempts.Add('Scoop app folder matched, but the Scoop command is unavailable.') }
        }
    } catch { $attempts.Add("Scoop uninstall error: $($_.Exception.Message)") }

    # WinGet fallback is attempted even when a registry entry exists but its native
    # uninstaller failed. Use the catalog's exact package ID, never a fuzzy name.
    $winget = Get-Command winget.exe -ErrorAction SilentlyContinue
    if ($winget -and -not [string]::IsNullOrWhiteSpace([string]$App.Id)) {
        try {
            $wgArgs = @('uninstall','--id',[string]$App.Id,'--exact','--accept-source-agreements')
            if ($Complete) { $wgArgs += '--purge' }
            $wgArgs += @('--silent','--disable-interactivity')
            $proc = Start-Process -FilePath $winget.Source -ArgumentList $wgArgs -PassThru -WindowStyle Hidden -ErrorAction Stop
            $uninstallExitCode = Wait-AMRUninstallProcess -Process $proc -AppName ([string]$App.Name)
            try { $proc.Dispose() } catch {}
            if ($uninstallExitCode -in @(0,1641,3010)) { return [pscustomobject]@{ Success=$true; Detail="WinGet exact-ID uninstall succeeded (exit $uninstallExitCode)." } }
            $attempts.Add("WinGet exact-ID uninstall returned exit code $uninstallExitCode.")
        } catch { $attempts.Add("WinGet uninstall error: $($_.Exception.Message)") }
    }

    # Chocolatey exact package ID fallback.
    $choco = Get-Command choco.exe -ErrorAction SilentlyContinue
    if ($choco -and -not [string]::IsNullOrWhiteSpace([string]$App.ChocoId)) {
        try {
            $proc = Start-Process -FilePath $choco.Source -ArgumentList @('uninstall',[string]$App.ChocoId,'-y','--no-progress') -PassThru -WindowStyle Hidden -ErrorAction Stop
            $uninstallExitCode = Wait-AMRUninstallProcess -Process $proc -AppName ([string]$App.Name)
            try { $proc.Dispose() } catch {}
            if ($uninstallExitCode -in @(0,1641,3010)) { return [pscustomobject]@{ Success=$true; Detail="Chocolatey exact-ID uninstall succeeded (exit $uninstallExitCode)." } }
            $attempts.Add("Chocolatey uninstall returned exit code $uninstallExitCode.")
        } catch { $attempts.Add("Chocolatey uninstall error: $($_.Exception.Message)") }
    }

    return [pscustomobject]@{ Success=$false; Detail=('All supported exact uninstall methods failed or were unavailable: ' + ($attempts -join ' | ')) }
}

function Invoke-AMRSelectedUninstall {
    if ($script:InstallRunning) { Show-AMRMessage 'Another software operation is currently running.' 'AMR Uninstall' OK Warning | Out-Null; return }
    if (-not $script:ShowInstalledOnly) { Show-AMRMessage 'Switch to Show Installed before using Uninstall.' 'AMR Uninstall' OK Warning | Out-Null; return }
    $selected = @($script:SoftwareCatalog | Where-Object { $_.IsSelected -eq $true -and $_.IsInstalled -eq $true })
    if ($selected.Count -eq 0) { Show-AMRMessage 'Select one or more detected installed applications first.' 'Selection Required' OK Warning | Out-Null; return }
    $choice = Show-AMRUninstallChoice -ApplicationNames @($selected | ForEach-Object { [string]$_.Name })
    if ($choice -eq 'Cancel') { return }

    $cleanupMap = @{}
    if ($choice -eq 'Complete') {
        foreach ($app in $selected) { $cleanupMap[[string]$app.Name] = @(Get-AMRSafeCleanupCandidates -App $app) }
        $previewLines = @()
        foreach ($app in $selected) {
            $paths = @($cleanupMap[[string]$app.Name])
            $previewLines += if ($paths.Count) { "• $($app.Name)`n  " + ($paths -join "`n  ") } else { "• $($app.Name): no additional app-specific folders verified" }
        }
        $preview = "Complete uninstall will remove only these verified app-specific folders after the native uninstall succeeds:`n`n" + ($previewLines -join "`n`n") + "`n`nPersonal files and shared folders are excluded. Continue?"
        $confirm = Show-AMRMessage $preview 'Confirm Complete Uninstall' YesNo Warning
        if ($confirm -ne [System.Windows.MessageBoxResult]::Yes) { return }
    } else {
        $confirm = Show-AMRMessage ("Uninstall the following application(s) while keeping their user data and settings?`n`n" + (($selected | ForEach-Object { '• ' + $_.Name }) -join "`n")) 'Confirm Uninstall' YesNo Warning
        if ($confirm -ne [System.Windows.MessageBoxResult]::Yes) { return }
    }

    Set-AMRInstallButtonsEnabled -Enabled $false
    $script:ProgressBar.IsIndeterminate = $false
    $script:ProgressBar.Value = 0
    $script:ProgressText.Text = "Uninstall queued: 0% (0/$($selected.Count) applications completed)."
    $success = 0; $failed = 0; $removedFolders = 0
    try {
        for ($i=0; $i -lt $selected.Count; $i++) {
            $app = $selected[$i]
            $script:ProgressBar.IsIndeterminate = $true
            $completedBefore = [math]::Round(($i / $selected.Count) * 100)
            $script:ProgressText.Text = "Uninstalling $($app.Name)... ($completedBefore% completed; current app in progress)"
            Write-AMRLog "Starting uninstall for '$($app.Name)' (mode: $choice)." INFO Software
            try {
                $result = Invoke-AMRExactNativeUninstall -App $app -KeepData:($choice -eq 'UninstallOnly') -Complete:($choice -eq 'Complete')
                if ($result.Success) {
                    $success++
                    Write-AMRLog "Uninstall succeeded for '$($app.Name)': $($result.Detail)" SUCCESS Software
                    if ($choice -eq 'Complete') {
                        [void](Remove-AMRExactUninstallRegistryEntry -AppName ([string]$app.Name))
                        foreach ($folderPath in @($cleanupMap[[string]$app.Name])) {
                            try {
                                $resolved = [IO.Path]::GetFullPath([string]$folderPath).TrimEnd('\')
                                if ((Test-Path -LiteralPath $resolved -PathType Container) -and [IO.Path]::GetFileName($resolved)) {
                                    Remove-Item -LiteralPath $resolved -Recurse -Force -ErrorAction Stop
                                    $removedFolders++
                                    Write-AMRLog "Removed verified app-specific folder: $resolved" SUCCESS Software
                                }
                            } catch { Write-AMRLog "Could not remove '$folderPath': $($_.Exception.Message)" WARNING Software }
                        }
                    }
                } else { $failed++; Write-AMRLog "Uninstall not completed for '$($app.Name)': $($result.Detail)" WARNING Software }
            } catch { $failed++; Write-AMRLog "Uninstall failed for '$($app.Name)': $($_.Exception.Message)" ERROR Software }
            $script:ProgressBar.IsIndeterminate = $false
            $script:ProgressBar.Value = [math]::Round((($i+1)/$selected.Count)*100)
            $script:ProgressText.Text = "Uninstall progress: $([int]$script:ProgressBar.Value)% ($($i+1)/$($selected.Count) applications completed)."
        }
    } finally {
        $script:ProgressBar.IsIndeterminate = $false
        Set-AMRInstallButtonsEnabled -Enabled $true
        try { Start-AMRInstalledCatalogScan -Refresh -ShowWhenReady:([bool]$script:ShowInstalledOnly) } catch { Write-AMRLog "Could not schedule the post-uninstall inventory refresh: $($_.Exception.Message)" WARNING Software }
        $script:AppsView.Refresh()
        foreach ($app in $script:SoftwareCatalog) { $app.IsSelected = $false }
    }
    $script:ProgressBar.IsIndeterminate = $false
    $script:ProgressBar.Value = 100
    $script:ProgressText.Text = "Uninstall finished: $success succeeded, $failed failed."
    Show-AMRMessage ("Uninstall summary`n`nSucceeded: $success`nFailed or unsupported: $failed`nApp-specific folders removed: $removedFolders`n`nSome uninstallers may request a restart.") 'AMR Uninstall Summary' OK Information | Out-Null
}

